import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import './index.css';
import Menu, { PauseMenu, Results } from './components/Menu';
import Hud, { Toast } from './components/Hud';
import { Game, GameResult, HudState } from './game/engine';
import { CraftId, diffById, loadSave, SaveData, storeSave } from './game/config';
import { sound } from './game/audio';

type Screen = 'menu' | 'play' | 'pause' | 'over';

const EMPTY_HUD: HudState = {
  health: 100, hunger: 100, energy: 100, day: 1, goal: 5, clock: '08:00', night: false, dayFrac: 0.33,
  inv: { madera: 0, piedra: 0, fruta: 1 }, tools: { hacha: 0, pico: 0, lanza: 0, fogata: 0 }, score: 0, prompt: '', boost: 0, hurt: 0, threats: 0,
};

export default function App() {
  const hostRef = useRef<HTMLDivElement>(null), gameRef = useRef<Game | null>(null);
  const [screen, setScreen] = useState<Screen>('menu'), screenRef = useRef<Screen>('menu');
  const [hud, setHud] = useState<HudState>(EMPTY_HUD);
  const [save, setSave] = useState<SaveData>(() => loadSave()), saveRef = useRef(save);
  const [result, setResult] = useState<{ r: GameResult; record: boolean } | null>(null);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [muted, setMuted] = useState(false);
  const [touch] = useState(() => typeof window !== 'undefined' && (window.matchMedia?.('(pointer: coarse)').matches ?? false));
  const timers = useRef<number[]>([]), toastId = useRef(0);

  const go = (s: Screen) => { screenRef.current = s; setScreen(s); };
  const persist = (s: SaveData) => { saveRef.current = s; setSave(s); storeSave(s); };

  useEffect(() => {
    const host = hostRef.current; if (!host) return;
    const game = new Game(host, {
      onHud: h => setHud(h),
      onEvent: (text, color) => {
        const id = ++toastId.current;
        setToasts(t => [...t.slice(-2), { id, text, color }]);
        timers.current.push(window.setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 2200));
      },
      onEnd: r => {
        const prev = saveRef.current, d = prev.diff;
        const record = r.score > (prev.best[d] ?? 0);
        persist({ ...prev, best: { ...prev.best, [d]: Math.max(prev.best[d] ?? 0, r.score) }, bestDays: Math.max(prev.bestDays, r.day), rescues: prev.rescues + (r.win ? 1 : 0) });
        setResult({ r, record }); go('over');
        if (r.win || record) {
          try { confetti({ particleCount: 170, spread: 110, origin: { y: 0.35 }, colors: ['#ff6b4a', '#ffd166', '#2ec4b6', '#fff6dc'] }); } catch { /* sin confeti */ }
        }
      },
    });
    gameRef.current = game;
    return () => { timers.current.forEach(t => window.clearTimeout(t)); timers.current = []; game.dispose(); gameRef.current = null; sound.dispose(); };
  }, []);

  const start = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    sound.init();
    (document.activeElement as HTMLElement | null)?.blur?.();
    setToasts([]); setResult(null); setHud({ ...EMPTY_HUD, goal: diffById(saveRef.current.diff).goal });
    g.newGame(diffById(saveRef.current.diff));
    go('play');
  }, []);

  const toMenu = useCallback(() => { gameRef.current?.toAttract(); setToasts([]); go('menu'); }, []);

  const setPaused = useCallback((p: boolean) => {
    const g = gameRef.current; if (!g) return;
    g.setPaused(p); go(p ? 'pause' : 'play');
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code !== 'Escape' && e.code !== 'KeyP') return;
      if (screenRef.current === 'play') setPaused(true); else if (screenRef.current === 'pause') setPaused(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [setPaused]);

  const toggleMute = () => { sound.init(); sound.setMuted(!muted); setMuted(!muted); };
  const craft = (id: CraftId) => gameRef.current?.craft(id);

  return (
    <div className="ip-root relative h-screen min-h-[420px] w-full overflow-hidden bg-[#0b3b4a]">
      <div ref={hostRef} className="absolute inset-0" />
      <div className="ip-vignette absolute inset-0" />

      {screen === 'menu' && (
        <Menu save={save} muted={muted} onMute={toggleMute} onPlay={start}
          onDiff={id => { sound.click(); persist({ ...saveRef.current, diff: id }); }} />
      )}

      {(screen === 'play' || screen === 'pause') && gameRef.current && (
        <Hud hud={hud} toasts={toasts} muted={muted} touch={touch} pad={gameRef.current.input.virtual}
          onPause={() => setPaused(true)} onMute={toggleMute} onCraft={craft} onEat={() => gameRef.current?.eat()} />
      )}

      {screen === 'pause' && <PauseMenu onResume={() => setPaused(false)} onRestart={start} onMenu={toMenu} />}

      {screen === 'over' && result && (
        <Results r={result.r} record={result.record} best={save.best[save.diff] ?? 0} onRetry={start} onMenu={toMenu} />
      )}
    </div>
  );
}

import { useRef, useState } from 'react';
import { Apple, Axe, Cherry, Flame, Footprints, Hand, Heart, Moon, Mountain, Pause, Pickaxe, Sparkles, Sun, Swords, TreePalm, Utensils, Volume2, VolumeX, Zap } from 'lucide-react';
import clsx from 'clsx';
import { canAfford, CraftId, RECIPES, Res } from '../game/config';
import { HudState } from '../game/engine';
import { VirtualPad } from '../game/input';

export interface Toast { id: number; text: string; color: string }
interface Props {
  hud: HudState; toasts: Toast[]; muted: boolean; touch: boolean; pad: VirtualPad;
  onPause(): void; onMute(): void; onCraft(id: CraftId): void; onEat(): void;
}

const CRAFT_ICON = { hacha: Axe, pico: Pickaxe, lanza: Swords, fogata: Flame };
const RES_INFO: Array<[Res, string, typeof TreePalm, string]> = [
  ['madera', 'Madera', TreePalm, '#d4a373'], ['piedra', 'Piedra', Mountain, '#cbd5e1'], ['fruta', 'Fruta', Cherry, '#ff6b6b'],
];

function Stat({ icon: Icon, label, value, color, warn }: { icon: typeof Heart; label: string; value: number; color: string; warn?: boolean }) {
  return (
    <div className="flex items-center gap-2">
      <Icon size={18} color={color} fill={warn ? color : 'none'} className={clsx(warn && 'ip-pulse')} />
      <div className="w-[118px] sm:w-[150px]">
        <div className="mb-0.5 flex justify-between text-[10px] font-black uppercase tracking-wider opacity-85"><span>{label}</span><span className="tabular-nums">{Math.round(value)}</span></div>
        <div className="ip-bar"><div style={{ width: `${Math.max(0, Math.min(100, value))}%`, background: `linear-gradient(90deg, ${color}aa, ${color})` }} /></div>
      </div>
    </div>
  );
}

function Joystick({ pad }: { pad: VirtualPad }) {
  const [knob, setKnob] = useState({ x: 0, y: 0 }); const origin = useRef<{ x: number; y: number } | null>(null);
  const move = (e: React.PointerEvent) => {
    if (!origin.current) return;
    let x = (e.clientX - origin.current.x) / 50, y = (e.clientY - origin.current.y) / 50; const l = Math.hypot(x, y);
    if (l > 1) { x /= l; y /= l; }
    pad.x = x; pad.y = y; setKnob({ x: x * 40, y: y * 40 });
  };
  const end = () => { origin.current = null; pad.x = 0; pad.y = 0; setKnob({ x: 0, y: 0 }); };
  return (
    <div className="pointer-events-auto relative h-32 w-32 rounded-full border-2 border-white/40 bg-[#0b2a33]/40 backdrop-blur-sm"
      onPointerDown={e => { const r = e.currentTarget.getBoundingClientRect(); origin.current = { x: r.left + r.width / 2, y: r.top + r.height / 2 }; e.currentTarget.setPointerCapture(e.pointerId); move(e); }}
      onPointerMove={move} onPointerUp={end} onPointerCancel={end}>
      <div className="absolute left-1/2 top-1/2 h-14 w-14 rounded-full border-2 border-[#0b2a33] bg-[#fff6dc]/90 shadow-lg" style={{ transform: `translate(calc(-50% + ${knob.x}px), calc(-50% + ${knob.y}px))` }} />
    </div>
  );
}

function TouchBtn({ k, pad, className, children }: { k: 'act' | 'eat' | 'run'; pad: VirtualPad; className?: string; children: React.ReactNode }) {
  const set = (v: boolean) => (e: React.PointerEvent) => { e.preventDefault(); pad[k] = v; };
  return <button onPointerDown={set(true)} onPointerUp={set(false)} onPointerLeave={set(false)} onPointerCancel={set(false)}
    className={clsx('ip-btn pointer-events-auto grid place-items-center rounded-full', className)}>{children}</button>;
}

export default function Hud({ hud, toasts, muted, touch, pad, onPause, onMute, onCraft, onEat }: Props) {
  const sunPos = ((hud.dayFrac - 0.25 + 1) % 1);
  return (
    <div className="pointer-events-none absolute inset-0 text-[#fff6dc]">
      {hud.hurt > 0 && <div className="ip-hurt absolute inset-0" style={{ opacity: hud.hurt }} />}

      {/* Estado vital */}
      <div className="ip-glass absolute left-2 top-2 flex flex-col gap-1.5 px-3 py-2.5 sm:left-4 sm:top-4">
        <Stat icon={Heart} label="Salud" value={hud.health} color="#ff5d5d" warn={hud.health < 30} />
        <Stat icon={Apple} label="Hambre" value={hud.hunger} color="#ffb347" warn={hud.hunger < 25} />
        <Stat icon={Zap} label="Energía" value={hud.energy} color="#ffe066" warn={hud.energy < 15} />
        {hud.boost > 0 && <div className="flex items-center gap-1 text-[11px] font-black text-[#ffd166]"><Sparkles size={13} /> Coco dorado {Math.ceil(hud.boost)}s</div>}
      </div>

      {/* Día y hora */}
      <div className="ip-glass absolute left-1/2 top-2 w-[190px] -translate-x-1/2 px-3 py-2 text-center sm:top-4 sm:w-[230px]">
        <div className="flex items-center justify-center gap-2">
          {hud.night ? <Moon size={18} className="text-[#a5b4fc]" /> : <Sun size={18} className="text-[#ffd166]" />}
          <span className="text-lg font-black">Día {hud.day}<span className="text-sm opacity-60">/{hud.goal}</span></span>
          <span className="font-mono text-sm font-bold tabular-nums opacity-85">{hud.clock}</span>
        </div>
        <div className="relative mt-1.5 h-2 rounded-full" style={{ background: 'linear-gradient(90deg,#ffb36b 0%,#7dd3fc 20%,#7dd3fc 45%,#ff9e64 52%,#1e2a5a 60%,#0b1430 90%,#ffb36b 100%)' }}>
          <div className="absolute top-1/2 h-3.5 w-3.5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white bg-[#0b2a33]" style={{ left: `${sunPos * 100}%` }} />
        </div>
        {hud.night && hud.threats > 0 && <div className="ip-pulse mt-1 text-[11px] font-black uppercase text-[#ff8f7a]">{hud.threats} cangrejos acechan</div>}
      </div>

      {/* Puntos y botones */}
      <div className="absolute right-2 top-2 flex flex-col items-end gap-2 sm:right-4 sm:top-4">
        <div className="flex gap-2">
          <div className="ip-glass px-3 py-1.5 text-right"><div className="text-[9px] font-black uppercase tracking-widest opacity-70">Puntos</div><div className="text-xl font-black leading-none tabular-nums">{hud.score}</div></div>
          <button onClick={onMute} className="ip-glass pointer-events-auto grid h-11 w-11 place-items-center">{muted ? <VolumeX size={18} /> : <Volume2 size={18} />}</button>
          <button onClick={onPause} className="ip-glass pointer-events-auto grid h-11 w-11 place-items-center"><Pause size={18} /></button>
        </div>
        <div className="ip-glass flex gap-3 px-3 py-2 sm:flex-col sm:gap-1.5">
          {RES_INFO.map(([k, label, Icon, c]) => (
            <div key={k} className="flex items-center gap-2" title={label}><Icon size={18} color={c} /><span className="w-6 text-lg font-black tabular-nums">{hud.inv[k]}</span><span className="hidden text-[10px] font-bold uppercase opacity-70 sm:inline">{label}</span></div>
          ))}
          {hud.inv.fruta > 0 && (
            <button onClick={onEat} className="pointer-events-auto mt-0.5 flex items-center justify-center gap-1 rounded-lg bg-[#ff6b4a] px-2 py-1 text-[11px] font-black text-white"><Utensils size={12} /> Comer (E)</button>
          )}
        </div>
      </div>

      {/* Avisos */}
      <div className="absolute left-1/2 top-[92px] flex -translate-x-1/2 flex-col items-center gap-1.5 sm:top-[104px]">
        {toasts.map(t => <div key={t.id} className="ip-toast whitespace-nowrap rounded-full bg-[#0b2a33]/80 px-4 py-1.5 text-sm font-black" style={{ color: t.color }}>{t.text}</div>)}
      </div>
      {hud.prompt && <div className={clsx('absolute left-1/2 -translate-x-1/2 rounded-full border-2 border-[#fff6dc]/60 bg-[#0b2a33]/75 px-4 py-1.5 text-sm font-black', touch ? 'bottom-[250px]' : 'bottom-[118px]')}>{hud.prompt}</div>}

      {/* Crafteo */}
      <div className={clsx('absolute left-1/2 flex -translate-x-1/2 gap-1.5 sm:gap-2', touch ? 'bottom-[170px]' : 'bottom-3 sm:bottom-4')}>
        {RECIPES.map(r => {
          const Icon = CRAFT_ICON[r.id], ok = canAfford(hud.inv, r), owned = r.id !== 'fogata' && hud.tools[r.id] > 0;
          return (
            <button key={r.id} onClick={() => onCraft(r.id)} disabled={owned}
              className={clsx('ip-glass pointer-events-auto relative w-[74px] px-1 py-1.5 text-center transition sm:w-[92px]', ok && !owned && 'ring-2 ring-[#ffd166]', owned && 'opacity-60', !ok && !owned && 'opacity-80')}>
              <span className="absolute left-1.5 top-1 rounded bg-white/20 px-1 font-mono text-[10px] font-black">{r.key}</span>
              <Icon size={22} className="mx-auto" color={owned ? '#86efac' : r.color} />
              <div className="text-[11px] font-black leading-tight">{r.name}</div>
              <div className="text-[9px] font-bold leading-tight opacity-75">{owned ? '✔ Equipada' : `${r.cost.madera ?? 0} mad · ${r.cost.piedra ?? 0} pie`}</div>
            </button>
          );
        })}
      </div>

      {touch && (
        <>
          <div className="absolute bottom-6 left-6"><Joystick pad={pad} /></div>
          <div className="absolute bottom-6 right-6 flex items-end gap-3">
            <div className="flex flex-col gap-3">
              <TouchBtn k="eat" pad={pad} className="h-14 w-14 bg-[#ffb347]"><Utensils size={22} /></TouchBtn>
              <TouchBtn k="run" pad={pad} className="h-14 w-14 bg-[#2ec4b6]"><Footprints size={22} /></TouchBtn>
            </div>
            <TouchBtn k="act" pad={pad} className="h-24 w-24 bg-[#ff6b4a] text-white"><Hand size={40} /></TouchBtn>
          </div>
        </>
      )}
    </div>
  );
}

import { Anchor, Axe, Flame, Footprints, House, Pause as PauseIcon, Play, RotateCcw, Ship, Skull, Sun, Trophy, Volume2, VolumeX } from 'lucide-react';
import clsx from 'clsx';
import { DIFFS, DiffId, SaveData } from '../game/config';
import { GameResult } from '../game/engine';

interface MenuProps { save: SaveData; muted: boolean; onMute(): void; onPlay(): void; onDiff(id: DiffId): void }

const CONTROLS: Array<[string, string]> = [
  ['↑ ↓ / W S', 'Caminar'], ['← → / A D', 'Girar'], ['Shift', 'Correr'], ['Espacio', 'Talar · picar · atacar'],
  ['E', 'Comer fruta'], ['1 – 4', 'Crear herramientas / fogata'], ['Esc / P', 'Pausa'],
];

export default function Menu({ save, muted, onMute, onPlay, onDiff }: MenuProps) {
  return (
    <div className="absolute inset-0 overflow-y-auto">
      <div className="flex min-h-full flex-col items-center justify-center gap-5 p-4 sm:flex-row sm:items-center sm:justify-start sm:gap-8 sm:p-10">
        <div className="ip-in w-full max-w-[460px]">
          <div className="ip-float mb-3 inline-flex items-center gap-2 rounded-full bg-[#0b2a33]/80 px-3 py-1 text-xs font-bold uppercase tracking-[0.25em] text-[#ffd166]">
            <Sun size={14} /> Supervivencia tropical
          </div>
          <h1 className="ip-title text-6xl sm:text-8xl">ISLA<br /><span className="ip-coral">PERDIDA</span></h1>
          <p className="mt-4 max-w-[400px] rounded-xl bg-[#0b2a33]/55 px-3 py-2 text-[15px] font-semibold leading-snug text-[#fff6dc] backdrop-blur">
            Naufragaste en una isla desconocida. Tala palmeras, pica rocas y recoge fruta, fabrica herramientas y enciende fogatas
            para resistir las noches infestadas de cangrejos hasta que llegue el barco de rescate.
          </p>
        </div>

        <div className="ip-paper ip-in w-full max-w-[400px] p-5 sm:ml-auto" style={{ animationDelay: '0.1s' }}>
          <div className="mb-2 flex items-center justify-between">
            <span className="text-xs font-black uppercase tracking-widest text-[#0f766e]">Dificultad</span>
            <button onClick={onMute} className="rounded-full p-1.5 text-[#0b2a33] hover:bg-black/10" aria-label="Silenciar">
              {muted ? <VolumeX size={18} /> : <Volume2 size={18} />}
            </button>
          </div>
          <div className="grid grid-cols-3 gap-2">
            {DIFFS.map(d => (
              <button key={d.id} onClick={() => onDiff(d.id)}
                className={clsx('rounded-xl border-2 border-[#0b2a33] px-2 py-2 text-left transition', save.diff === d.id ? 'bg-[#2ec4b6] text-[#0b2a33] shadow-[0_3px_0_#0b2a33]' : 'bg-white/60 hover:bg-white')}>
                <div className="text-sm font-black">{d.name}</div>
                <div className="text-[11px] font-semibold opacity-75">{d.desc}</div>
              </button>
            ))}
          </div>
          <div className="mt-3 flex items-center gap-3 rounded-xl bg-[#0b2a33] px-3 py-2 text-[#fff6dc]">
            <Trophy size={20} className="text-[#ffd166]" />
            <div className="flex-1 text-xs font-bold uppercase tracking-wide opacity-80">Récord</div>
            <div className="text-xl font-black tabular-nums">{save.best[save.diff] ?? 0}</div>
            <div className="flex items-center gap-1 text-xs font-bold opacity-80"><Ship size={14} /> {save.rescues}</div>
          </div>
          <div className="mt-3 grid grid-cols-2 gap-x-3 gap-y-1 text-[12px]">
            {CONTROLS.map(([k, v]) => (
              <div key={k} className="flex items-center gap-1.5"><kbd className="rounded-md border border-[#0b2a33]/40 bg-white px-1.5 py-0.5 font-mono text-[10px] font-bold">{k}</kbd><span className="font-semibold opacity-80">{v}</span></div>
            ))}
          </div>
          <button onClick={onPlay} className="ip-btn mt-4 flex w-full items-center justify-center gap-2 bg-[#ff6b4a] py-3 text-2xl text-white">
            <Play size={24} fill="currentColor" /> Jugar
          </button>
        </div>
      </div>
    </div>
  );
}

export function PauseMenu({ onResume, onRestart, onMenu }: { onResume(): void; onRestart(): void; onMenu(): void }) {
  return (
    <div className="absolute inset-0 grid place-items-center bg-[#0b2a33]/55 p-4 backdrop-blur-sm">
      <div className="ip-paper ip-in w-full max-w-[320px] p-6 text-center">
        <PauseIcon className="mx-auto mb-1 text-[#0f766e]" size={34} />
        <h2 className="ip-title mb-4 text-4xl">PAUSA</h2>
        <div className="flex flex-col gap-3">
          <button onClick={onResume} className="ip-btn flex items-center justify-center gap-2 bg-[#2ec4b6] py-2.5 text-lg"><Play size={20} /> Continuar</button>
          <button onClick={onRestart} className="ip-btn flex items-center justify-center gap-2 bg-[#ffd166] py-2.5 text-lg"><RotateCcw size={20} /> Reiniciar</button>
          <button onClick={onMenu} className="ip-btn flex items-center justify-center gap-2 bg-white py-2.5 text-lg"><House size={20} /> Menú</button>
        </div>
      </div>
    </div>
  );
}

export function Results({ r, record, best, onRetry, onMenu }: { r: GameResult; record: boolean; best: number; onRetry(): void; onMenu(): void }) {
  const stats: Array<[React.ReactNode, string, number | string]> = [
    [<Sun size={16} />, 'Días sobrevividos', r.day], [<Skull size={16} />, 'Cangrejos vencidos', r.kills],
    [<Axe size={16} />, 'Recursos reunidos', r.gathered], [<Flame size={16} />, 'Objetos creados', r.crafted],
  ];
  return (
    <div className="absolute inset-0 grid place-items-center overflow-y-auto bg-[#0b2a33]/60 p-4 backdrop-blur-sm">
      <div className="ip-paper ip-in w-full max-w-[380px] p-6 text-center">
        {r.win ? <Anchor className="mx-auto text-[#0f766e]" size={40} /> : <Footprints className="mx-auto text-[#c2410c]" size={40} />}
        <h2 className={clsx('ip-title mt-1 text-4xl sm:text-5xl', !r.win && 'ip-coral')}>{r.win ? '¡RESCATADO!' : 'FIN DEL VIAJE'}</h2>
        <p className="mt-1 text-sm font-bold text-[#0b2a33]/75">{r.cause}</p>
        <div className="my-4 rounded-2xl bg-[#0b2a33] py-3 text-[#fff6dc]">
          <div className="text-xs font-bold uppercase tracking-widest opacity-75">Puntuación</div>
          <div className="text-5xl font-black tabular-nums">{r.score}</div>
          {record ? <div className="ip-pulse mt-1 text-sm font-black text-[#ffd166]">¡NUEVO RÉCORD!</div> : <div className="mt-1 text-xs opacity-70">Récord: {best}</div>}
        </div>
        <div className="mb-5 grid grid-cols-2 gap-2 text-left">
          {stats.map(([icon, label, v]) => (
            <div key={label} className="flex items-center gap-2 rounded-xl bg-white/70 px-2.5 py-2">
              <span className="text-[#0f766e]">{icon}</span><div><div className="text-lg font-black leading-none">{v}</div><div className="text-[10px] font-bold uppercase opacity-70">{label}</div></div>
            </div>
          ))}
        </div>
        <div className="flex gap-3">
          <button onClick={onRetry} className="ip-btn flex flex-1 items-center justify-center gap-2 bg-[#ff6b4a] py-2.5 text-lg text-white"><RotateCcw size={20} /> Reintentar</button>
          <button onClick={onMenu} className="ip-btn flex items-center justify-center gap-2 bg-white px-4 py-2.5 text-lg"><House size={20} /></button>
        </div>
      </div>
    </div>
  );
}

// Audio procedural con Web Audio: efectos, oleaje ambiental y una melodía tropical suave.
class Sound {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private noise: AudioBuffer | null = null;
  private musicTimer = 0; private step = 0;
  muted = false;
  night = false;

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {}); return; }
    try {
      const AC = window.AudioContext || (window as any).webkitAudioContext;
      this.ctx = new AC();
      this.master = this.ctx.createGain(); this.master.gain.value = this.muted ? 0 : 0.5;
      this.master.connect(this.ctx.destination);
      const len = this.ctx.sampleRate * 2, buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate), d = buf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      this.noise = buf;
      this.startOcean();
      this.musicTimer = window.setInterval(() => this.music(), 260);
    } catch { this.ctx = null; }
  }
  setMuted(m: boolean) { this.muted = m; if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.5, this.ctx.currentTime, 0.05); }

  private startOcean() {
    const c = this.ctx!, src = c.createBufferSource(); src.buffer = this.noise; src.loop = true;
    const f = c.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 500;
    const g = c.createGain(); g.gain.value = 0.05;
    const lfo = c.createOscillator(), lg = c.createGain(); lfo.frequency.value = 0.12; lg.gain.value = 0.04;
    lfo.connect(lg).connect(g.gain); lfo.start();
    src.connect(f).connect(g).connect(this.master!); src.start();
  }
  private tone(freq: number, dur: number, type: OscillatorType = 'sine', vol = 0.2, slide = 0, delay = 0) {
    const c = this.ctx; if (!c || !this.master) return;
    const t = c.currentTime + delay, o = c.createOscillator(), g = c.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur);
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(this.master); o.start(t); o.stop(t + dur + 0.05);
  }
  private burst(dur: number, freq: number, vol = 0.3, type: BiquadFilterType = 'bandpass') {
    const c = this.ctx; if (!c || !this.master || !this.noise) return;
    const s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain(), t = c.currentTime;
    s.buffer = this.noise; f.type = type; f.frequency.value = freq; f.Q.value = 1.2;
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    s.connect(f).connect(g).connect(this.master); s.start(t, Math.random()); s.stop(t + dur + 0.05);
  }
  private music() {
    if (!this.ctx || this.muted) return;
    const scale = this.night ? [220, 261.6, 293.7, 329.6, 392] : [392, 440, 523.3, 587.3, 659.3, 784];
    const pat = [0, 2, 4, 2, 1, 3, 5, 3, 0, 4, 2, 1, -1, 2, 3, -1];
    const n = pat[this.step++ % pat.length];
    if (n >= 0 && n < scale.length) this.tone(scale[n], this.night ? 0.6 : 0.3, this.night ? 'sine' : 'triangle', this.night ? 0.03 : 0.045);
    if (this.step % 8 === 1) this.tone(scale[0] / 2, 0.8, 'sine', 0.05);
  }
  chop() { this.burst(0.12, 900, 0.4); this.tone(140, 0.1, 'square', 0.08, -60); }
  stone() { this.burst(0.08, 3200, 0.35, 'highpass'); this.tone(900, 0.06, 'square', 0.05, -400); }
  pick() { this.tone(660, 0.08, 'triangle', 0.15); this.tone(990, 0.1, 'triangle', 0.12, 0, 0.06); }
  eat() { this.burst(0.06, 1400, 0.25); this.burst(0.06, 1200, 0.25); this.tone(500, 0.12, 'sine', 0.12, 200, 0.1); }
  craft() { [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.18, 'triangle', 0.14, 0, i * 0.07)); }
  hit() { this.tone(300, 0.1, 'square', 0.12, -200); this.burst(0.1, 600, 0.3); }
  hurt() { this.tone(180, 0.25, 'sawtooth', 0.18, -100); }
  crabDie() { this.tone(700, 0.25, 'square', 0.1, -600); this.burst(0.15, 2000, 0.2); }
  chest() { [784, 988, 1175, 1568].forEach((f, i) => this.tone(f, 0.3, 'sine', 0.13, 0, i * 0.08)); }
  fire() { this.burst(0.6, 400, 0.3, 'lowpass'); this.tone(220, 0.3, 'sine', 0.1, 220); }
  nightfall() { this.tone(196, 1.4, 'sine', 0.14, -60); this.tone(147, 1.6, 'sine', 0.1, -40, 0.2); }
  dawn() { [392, 494, 587, 784].forEach((f, i) => this.tone(f, 0.5, 'sine', 0.1, 0, i * 0.12)); }
  click() { this.tone(880, 0.05, 'square', 0.06); }
  over(win: boolean) { (win ? [523, 659, 784, 1046, 1318] : [392, 330, 262, 196]).forEach((f, i) => this.tone(f, 0.35, 'triangle', 0.15, 0, i * 0.14)); }

  dispose() { window.clearInterval(this.musicTimer); this.ctx?.close().catch(() => {}); this.ctx = null; }
}
