export type DiffId = 'facil' | 'normal' | 'naufrago';
export interface Difficulty {
  id: DiffId; name: string; desc: string; goal: number; dayLen: number;
  hunger: number; crabRate: number; crabDmg: number; maxCrabs: number;
}
export const DIFFS: Difficulty[] = [
