  { id: 'naufrago', name: 'Náufrago', desc: 'Rescate al día 7', goal: 7, dayLen: 95, hunger: 0.7, crabRate: 1.4, crabDmg: 1.3, maxCrabs: 13 },
];
export const diffById = (id: DiffId) => DIFFS.find(d => d.id === id) ?? DIFFS[1];

export type Res = 'madera' | 'piedra' | 'fruta';
export type Inventory = Record<Res, number>;
export type CraftId = 'hacha' | 'pico' | 'lanza' | 'fogata';
export interface Recipe { id: CraftId; name: string; key: string; cost: Partial<Inventory>; desc: string; color: string }
export const RECIPES: Recipe[] = [
