export const canAfford = (inv: Inventory, r: Recipe) => (Object.keys(r.cost) as Res[]).every(k => inv[k] >= (r.cost[k] ?? 0));

export interface SaveData { diff: DiffId; best: Partial<Record<DiffId, number>>; bestDays: number; rescues: number }
const KEY = 'isla-perdida-save-v1';
export function loadSave(): SaveData {
  const def: SaveData = { diff: 'normal', best: {}, bestDays: 0, rescues: 0 };
  try { const s = localStorage.getItem(KEY); return s ? { ...def, ...JSON.parse(s) } : def; } catch { return def; }
}
export function storeSave(s: SaveData) { try { localStorage.setItem(KEY, JSON.stringify(s)); } catch { /* sin almacenamiento */ } }

/** Hora del día (0..1, 0.25 = amanecer, 0.5 = mediodía, 0.75 = atardecer) → texto "HH:MM". */
export function clock(t: number) {
  const m = Math.floor(((t % 1) * 24 * 60)), h = Math.floor(m / 60);
  return `${String(h).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
}
export const isNight = (t: number) => { const f = t % 1; return f > 0.8 || f < 0.21; };

import * as THREE from 'three';
import { lin } from './three-compat';
import { heightAt, ISLAND_R } from './world';

export type CrabType = 'peque' | 'rojo' | 'azul' | 'gigante';
export const CRAB_INFO: Record<CrabType, { name: string; hp: number; speed: number; dmg: number; scale: number; color: string; score: number; passive?: boolean }> = {
  peque: { name: 'Cangrejito', hp: 1, speed: 2.4, dmg: 0, scale: 0.6, color: '#ff9e5e', score: 10, passive: true },
  rojo: { name: 'Cangrejo rojo', hp: 2, speed: 3.4, dmg: 8, scale: 1, color: '#e63946', score: 25 },
  azul: { name: 'Cangrejo azul', hp: 1, speed: 5.2, dmg: 5, scale: 0.8, color: '#3a86ff', score: 30 },
  gigante: { name: 'Cangrejo gigante', hp: 6, speed: 2.5, dmg: 16, scale: 1.9, color: '#8d0801', score: 90 },
};

interface Crab {
  g: THREE.Group; legs: THREE.Object3D[]; clawL: THREE.Object3D; clawR: THREE.Object3D; mat: THREE.MeshStandardMaterial;
  active: boolean; type: CrabType; hp: number; vx: number; vz: number; heading: number; wander: number; atk: number; hurt: number; dying: number; t: number; flee: boolean;
}

export interface CrabCtx { player: THREE.Vector3; night: boolean; fires: THREE.Vector3[]; dmgK: number }

export class Crabs {
  readonly group = new THREE.Group();
  private pool: Crab[] = [];
  private geo = { body: new THREE.SphereGeometry(0.5, 8, 5), leg: new THREE.BoxGeometry(0.5, 0.06, 0.06), claw: new THREE.BoxGeometry(0.28, 0.18, 0.22), eye: new THREE.SphereGeometry(0.06, 5, 4), stalk: new THREE.CylinderGeometry(0.025, 0.025, 0.22, 4) };
  private eyeMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.3, emissive: new THREE.Color(0x220000) });
  onBite: (dmg: number, x: number, z: number) => void = () => {};

  constructor() {
    for (let i = 0; i < 18; i++) {
      const g = new THREE.Group(), mat = new THREE.MeshStandardMaterial({ color: 0xff0000, flatShading: true, roughness: 0.5 });
      const body = new THREE.Mesh(this.geo.body, mat); body.scale.set(1, 0.45, 0.78); body.position.y = 0.32; body.castShadow = true; g.add(body);
      const legs: THREE.Object3D[] = [];
      for (let s = -1; s <= 1; s += 2) for (let k = 0; k < 3; k++) {
        const p = new THREE.Group(); p.position.set(s * 0.38, 0.3, (k - 1) * 0.22); p.rotation.y = s < 0 ? Math.PI : 0;
        const l = new THREE.Mesh(this.geo.leg, mat); l.position.x = 0.22; l.rotation.z = -0.6; p.add(l); g.add(p); legs.push(p);
      }
      const mkClaw = (s: number) => {
        const c = new THREE.Group(); c.position.set(s * 0.32, 0.38, 0.42);
        const arm = new THREE.Mesh(this.geo.leg, mat); arm.scale.set(0.6, 1.4, 1.4); arm.rotation.y = s * 1.1; arm.position.z = 0.05; c.add(arm);
        const pin = new THREE.Mesh(this.geo.claw, mat); pin.position.set(s * 0.05, 0.05, 0.25); pin.castShadow = true; c.add(pin);
        g.add(c); return c;
      };
      const clawL = mkClaw(-1), clawR = mkClaw(1);
      for (const s of [-1, 1]) {
        const st = new THREE.Mesh(this.geo.stalk, mat); st.position.set(s * 0.12, 0.5, 0.3); g.add(st);
        const e = new THREE.Mesh(this.geo.eye, this.eyeMat); e.position.set(s * 0.12, 0.62, 0.3); g.add(e);
      }
      g.visible = false; this.group.add(g);
      this.pool.push({ g, legs, clawL, clawR, mat, active: false, type: 'rojo', hp: 1, vx: 0, vz: 0, heading: 0, wander: 0, atk: 0, hurt: 0, dying: 0, t: Math.random() * 9, flee: false });
    }
  }

  get count() { return this.pool.filter(c => c.active && c.dying <= 0).length; }
  hostileCount() { return this.pool.filter(c => c.active && c.dying <= 0 && !CRAB_INFO[c.type].passive).length; }

  spawn(type: CrabType, x: number, z: number) {
    const c = this.pool.find(p => !p.active); if (!c) return null;
    const info = CRAB_INFO[type];
    Object.assign(c, { active: true, type, hp: info.hp, vx: 0, vz: 0, heading: Math.random() * 6.28, wander: 0, atk: 1, hurt: 0, dying: 0, flee: false });
    c.mat.color.copy(lin(info.color)); c.mat.emissive.setRGB(0, 0, 0);
    c.g.scale.setScalar(info.scale); c.g.position.set(x, heightAt(x, z), z); c.g.rotation.set(0, 0, 0); c.g.visible = true;
    return c;
  }
  /** Busca un punto de playa a cierta distancia del jugador. */
  beachPoint(px: number, pz: number, minD: number, maxD: number) {
    for (let i = 0; i < 40; i++) {
      const a = Math.random() * 6.283, d = minD + Math.random() * (maxD - minD), x = px + Math.cos(a) * d, z = pz + Math.sin(a) * d, h = heightAt(x, z);
      if (h > -0.3 && h < 1.2) return { x, z };
    }
    return null;
  }

  /** Golpe del jugador: daña al cangrejo más cercano en el cono frontal. */
  strike(p: THREE.Vector3, fwd: THREE.Vector3, range: number, dmg: number) {
    let best: Crab | null = null, bd = Infinity;
    for (const c of this.pool) {
      if (!c.active || c.dying > 0) continue;
      const dx = c.g.position.x - p.x, dz = c.g.position.z - p.z, d = Math.hypot(dx, dz) - CRAB_INFO[c.type].scale * 0.4;
      if (d < range && (dx * fwd.x + dz * fwd.z) / (Math.hypot(dx, dz) || 1) > 0.3 && d < bd) { bd = d; best = c; }
    }
    if (!best) return null;
    best.hp -= dmg; best.hurt = 0.25; best.flee = true;
    const k = 7 / CRAB_INFO[best.type].scale; best.vx += fwd.x * k; best.vz += fwd.z * k;
    if (best.hp <= 0) best.dying = 0.6;
    return { type: best.type, killed: best.hp <= 0, pos: best.g.position.clone() };
  }
  nearestHostile(p: THREE.Vector3, range: number) {
    return this.pool.some(c => c.active && c.dying <= 0 && Math.hypot(c.g.position.x - p.x, c.g.position.z - p.z) < range);
  }

  update(dt: number, ctx: CrabCtx) {
    for (const c of this.pool) {
      if (!c.active) continue;
      const info = CRAB_INFO[c.type], pos = c.g.position;
      c.t += dt;
      if (c.dying > 0) {
        c.dying -= dt; c.g.rotation.z += dt * 9; pos.y += dt * 1.5; c.g.scale.setScalar(info.scale * Math.max(0.01, c.dying / 0.6));
        if (c.dying <= 0) { c.active = false; c.g.visible = false; }
        continue;
      }
      let tx = 0, tz = 0, spd = info.speed;
      const dx = ctx.player.x - pos.x, dz = ctx.player.z - pos.z, dist = Math.hypot(dx, dz) || 1;
      const nearFire = ctx.fires.find(f => Math.hypot(f.x - pos.x, f.z - pos.z) < 8);
      const retreat = !info.passive && !ctx.night;
      if (nearFire) { tx = pos.x - nearFire.x; tz = pos.z - nearFire.z; spd *= 1.3; }
      else if (retreat) { tx = pos.x; tz = pos.z; spd *= 0.9; }
      else if (info.passive || dist > 34) {
        c.wander -= dt;
        if (c.wander <= 0) { c.wander = 1 + Math.random() * 2.5; c.heading = Math.random() * 6.283; }
        tx = Math.cos(c.heading); tz = Math.sin(c.heading);
        if (info.passive && c.flee && dist < 7) { tx = -dx; tz = -dz; spd *= 1.6; } else if (info.passive) spd *= 0.5;
        if (!info.passive) { tx = tx * 0.4 + dx / dist; tz = tz * 0.4 + dz / dist; spd *= 0.6; }
        if (heightAt(pos.x + tx, pos.z + tz) > 2.5 && info.passive) { tx = pos.x; tz = pos.z; }
      } else { tx = dx; tz = dz; if (dist < 1.1 + info.scale * 0.5) spd = 0; }
      const tl = Math.hypot(tx, tz) || 1;
      pos.x += ((tx / tl) * spd + c.vx) * dt; pos.z += ((tz / tl) * spd + c.vz) * dt;
      c.vx *= Math.max(0, 1 - dt * 5); c.vz *= Math.max(0, 1 - dt * 5);
      if (Math.hypot(pos.x, pos.z) > ISLAND_R * 1.25) { pos.x *= 0.99; pos.z *= 0.99; }
      const h = heightAt(pos.x, pos.z);
      pos.y += (h - pos.y) * Math.min(1, dt * 10);
      if ((retreat && h < -1.5) || (info.passive && !c.flee && h < -2)) { c.active = false; c.g.visible = false; continue; }
      // Los cangrejos caminan de lado: el cuerpo mira perpendicular al avance (pero encaran al jugador al atacar)
      const face = !info.passive && !retreat && !nearFire && dist < 6 ? Math.atan2(dx, dz) : Math.atan2(tx, tz) + Math.PI / 2;
      let dr = face - c.g.rotation.y; while (dr > Math.PI) dr -= Math.PI * 2; while (dr < -Math.PI) dr += Math.PI * 2;
      c.g.rotation.y += dr * Math.min(1, dt * 8);
      const moving = spd > 0.1 ? 1 : 0.2;
      c.legs.forEach((l, i) => { l.rotation.z = Math.sin(c.t * 22 + i * 1.7) * 0.45 * moving; });
      const snap = Math.max(0, Math.sin(c.t * (ctx.night ? 9 : 4)));
      c.clawL.rotation.x = -snap * 0.5; c.clawR.rotation.x = -Math.max(0, Math.sin(c.t * 9 + 1.5)) * 0.5;
      c.hurt = Math.max(0, c.hurt - dt);
      c.mat.emissive.setRGB(c.hurt > 0 ? 0.9 : ctx.night && !info.passive ? 0.18 : 0, c.hurt > 0 ? 0.9 : 0.02, c.hurt > 0 ? 0.9 : 0);
      c.atk -= dt;
      if (info.dmg > 0 && !retreat && !nearFire && dist < 1.25 + info.scale * 0.55 && c.atk <= 0) {
        c.atk = 1.1; c.clawL.rotation.x = c.clawR.rotation.x = -1;
        this.onBite(info.dmg * ctx.dmgK, pos.x, pos.z);
      }
    }
  }
  clear() { for (const c of this.pool) { c.active = false; c.g.visible = false; } }
  dispose() {
    Object.values(this.geo).forEach(g => g.dispose()); this.eyeMat.dispose(); this.pool.forEach(c => c.mat.dispose());
  }
}

import * as THREE from 'three';
import { setupRenderer } from './three-compat';
import { heightAt, World } from './world';
import { Flora, ResNode } from './flora';
import { Player, ToolId } from './player';
import { CRAB_INFO, CrabType, Crabs } from './crabs';
import { FIRE_FUEL, Props } from './props';
import { Input } from './input';
import { sound } from './audio';
import { canAfford, clock, CraftId, Difficulty, Inventory, isNight, RECIPES, Res } from './config';

export interface HudState {
  health: number; hunger: number; energy: number; day: number; goal: number; clock: string; night: boolean; dayFrac: number;
  inv: Inventory; tools: Record<CraftId, number>; score: number; prompt: string; boost: number; hurt: number; threats: number;
}
export interface GameResult { win: boolean; day: number; score: number; kills: number; crafted: number; gathered: number; cause: string }
interface Callbacks { onHud(h: HudState): void; onEvent(text: string, color: string): void; onEnd(r: GameResult): void }

const START_T = 0.33;

export class Game {
  readonly input = new Input();
  private renderer: THREE.WebGLRenderer; private scene = new THREE.Scene(); private camera: THREE.PerspectiveCamera;
  private world: World; private flora: Flora; private player = new Player(); private crabs = new Crabs(); private props = new Props();
  private ro: ResizeObserver; private raf = 0; private last = performance.now(); private elapsed = 0;
  private mode: 'attract' | 'play' | 'over' = 'attract'; private paused = false;
  private diff!: Difficulty;
  private t = START_T; private health = 100; private hunger = 100; private energy = 100;
  private inv: Inventory = { madera: 0, piedra: 0, fruta: 0 }; private tools: Record<CraftId, number> = { hacha: 0, pico: 0, lanza: 0, fogata: 0 };
  private score = 0; private kills = 0; private crafted = 0; private gathered = 0; private boost = 0; private hurtFlash = 0;
  private actCd = 0; private spawnCd = 0; private passiveCd = 0; private hudCd = 0; private shake = 0; private wasNight = false; private dayShown = 1;
  private camPos = new THREE.Vector3(); private camLook = new THREE.Vector3(); private prompt = '';

  constructor(private host: HTMLElement, private cb: Callbacks) {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    setupRenderer(this.renderer);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.shadowMap.enabled = true; this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.domElement.style.cssText = 'display:block;width:100%;height:100%';
    host.appendChild(this.renderer.domElement);
    this.camera = new THREE.PerspectiveCamera(58, 1, 0.1, 1500);
    this.world = new World(this.scene);
    this.flora = new Flora();
    this.scene.add(this.flora.group, this.player.group, this.crabs.group, this.props.group);
    this.crabs.onBite = (dmg) => this.bite(dmg);
    this.ro = new ResizeObserver(() => this.resize()); this.ro.observe(host); this.resize();
    this.player.reset(this.flora.spawn.x, this.flora.spawn.z, this.flora.spawn.yaw);
    this.raf = requestAnimationFrame(this.loop);
  }

  private resize() {
    const w = Math.max(1, this.host.clientWidth), h = Math.max(1, this.host.clientHeight);
    this.renderer.setSize(w, h, false); this.camera.aspect = w / h;
    this.camera.fov = w / h < 0.8 ? 72 : 58; this.camera.updateProjectionMatrix();
  }

  toAttract() { this.mode = 'attract'; this.paused = false; this.crabs.clear(); this.props.clear(); this.input.reset(); }
  setPaused(p: boolean) { this.paused = p; this.input.reset(); }

  newGame(diff: Difficulty) {
    this.diff = diff; this.mode = 'play'; this.paused = false; this.input.reset();
    Object.assign(this, { t: START_T, health: 100, hunger: 100, energy: 100, score: 0, kills: 0, crafted: 0, gathered: 0, boost: 0, hurtFlash: 0, actCd: 0, spawnCd: 4, passiveCd: 3, shake: 0, wasNight: false, dayShown: 1 });
    this.inv = { madera: 0, piedra: 0, fruta: 1 }; this.tools = { hacha: 0, pico: 0, lanza: 0, fogata: 0 };
    this.crabs.clear(); this.props.clear();
    for (const n of this.flora.nodes) if (n.hp < n.max) { n.hp = n.max; n.regrow = 0; this.flora.hit(n, 0); }
    const s = this.flora.spawn; this.player.reset(s.x, s.z, s.yaw); this.player.setTool(null);
    // Acción inmediata: cangrejitos y un cofre cerca del inicio
    for (let i = 0; i < 4; i++) { const a = s.yaw + (i - 1.5) * 0.45, d = 5 + i * 1.6; this.crabs.spawn('peque', s.x + Math.sin(a) * d, s.z + Math.cos(a) * d); }
    const cp = this.crabs.beachPoint(s.x, s.z, 9, 16); if (cp) this.props.spawnChest(cp.x, cp.z);
    this.snapCamera();
    this.cb.onEvent('Día 1 · ¡Sobrevive hasta el rescate!', '#ffd23f');
  }

  craft(id: CraftId) {
    if (this.mode !== 'play' || this.paused) return;
    const r = RECIPES.find(x => x.id === id)!;
    if (id !== 'fogata' && this.tools[id]) { this.cb.onEvent(`Ya tienes ${r.name.toLowerCase()}`, '#e2e8f0'); return; }
    if (!canAfford(this.inv, r)) { this.cb.onEvent(`Faltan materiales para ${r.name.toLowerCase()}`, '#fca5a5'); sound.click(); return; }
    (Object.keys(r.cost) as Res[]).forEach(k => (this.inv[k] -= r.cost[k] ?? 0));
    this.tools[id]++; this.crafted++; this.score += 30;
    if (id === 'fogata') {
      const f = this.player.forward, p = this.player.pos;
      this.props.placeFire(p.x + f.x * 2, p.z + f.z * 2); sound.fire();
    } else { this.player.setTool(id as ToolId); this.player.swing = 1; }
    sound.craft(); this.cb.onEvent(`¡${r.name} creada!`, r.color);
  }
  eat() {
    if (this.mode !== 'play' || this.paused) return;
    if (this.inv.fruta <= 0) { this.cb.onEvent('No tienes fruta', '#fca5a5'); return; }
    this.inv.fruta--; this.hunger = Math.min(100, this.hunger + 26); this.health = Math.min(100, this.health + 6); this.energy = Math.min(100, this.energy + 8);
    sound.eat(); this.props.burst(this.player.pos.clone().setY(this.player.pos.y + 1.6), '#e63946', 8, 2);
  }

  private bite(dmg: number) {
    if (this.mode !== 'play') return;
    this.health -= dmg; this.player.hurt = 0.6; this.hurtFlash = 1; this.shake = 0.5; sound.hurt();
    if (this.health <= 0) this.end(false, 'Los cangrejos te vencieron');
  }

  private end(win: boolean, cause: string) {
    if (this.mode !== 'play') return;
    this.mode = 'over'; sound.over(win);
    if (win) this.score += 1000;
    this.cb.onEnd({ win, day: this.day, score: Math.round(this.score), kills: this.kills, crafted: this.crafted, gathered: this.gathered, cause });
  }

  private get day() { return Math.floor(this.t - 0.25) + 1; }

  private action() {
    const p = this.player.pos, f = this.player.forward, lanza = this.tools.lanza > 0;
    this.player.swing = 1; this.actCd = 0.42; this.energy = Math.max(0, this.energy - 1.5);
    const tired = this.energy <= 0 ? 0.5 : 1;
    const hit = this.crabs.strike(p, f, lanza ? 3.1 : 2.2, (lanza ? 3 : this.tools.hacha ? 2 : 1));
    if (hit) {
      this.player.setTool(lanza ? 'lanza' : this.tools.hacha ? 'hacha' : null); sound.hit(); this.shake = 0.15;
      this.props.burst(hit.pos.clone().setY(hit.pos.y + 0.5), CRAB_INFO[hit.type].color, 8, 4);
      if (hit.killed) {
        const info = CRAB_INFO[hit.type]; this.kills++; this.score += info.score; this.inv.fruta += hit.type === 'gigante' ? 3 : 1; sound.crabDie();
        this.cb.onEvent(`${info.name} +${info.score} · +${hit.type === 'gigante' ? 3 : 1} comida`, '#fb923c');
      }
      return;
    }
    const chest = this.props.nearChest(p, 2.4);
    if (chest) { this.props.openChest(chest); this.loot(); return; }
    const fire = this.props.nearFire(p, 2.6);
    if (fire && this.inv.madera >= 2 && fire.fuel < FIRE_FUEL - 20) { this.inv.madera -= 2; fire.fuel = Math.min(FIRE_FUEL, fire.fuel + 60); sound.fire(); this.cb.onEvent('Leña añadida a la fogata', '#fb923c'); return; }
    const n = this.flora.nearest(p.x, p.z, f.x, f.z, 2.1);
    if (n) this.gather(n, tired);
  }

  private gather(n: ResNode, tired: number) {
    const at = new THREE.Vector3(n.x, n.y + (n.kind === 'palm' ? 1.4 : 0.7), n.z);
    let res: Res, amount = 1, dmg = tired < 1 ? 0.5 : 1;
    if (n.kind === 'palm') { res = 'madera'; if (this.tools.hacha) { amount = 2; dmg *= 2; } this.player.setTool(this.tools.hacha ? 'hacha' : null); sound.chop(); this.props.burst(at, '#c08a52', 6, 3.5); }
    else if (n.kind === 'rock') { res = 'piedra'; if (this.tools.pico) { amount = 2; dmg *= 2; } this.player.setTool(this.tools.pico ? 'pico' : null); sound.stone(); this.props.burst(at, '#a8a39a', 6, 4); }
    else { res = 'fruta'; sound.pick(); this.props.burst(at, '#e63946', 5, 2.5); }
    const felled = this.flora.hit(n, dmg);
    if (felled && n.kind !== 'bush') { amount += 2; this.cb.onEvent(n.kind === 'palm' ? '¡Palmera talada!' : '¡Roca partida!', '#fde68a'); if (n.kind === 'palm' && Math.random() < 0.6) this.inv.fruta++; }
    this.inv[res] += amount; this.gathered += amount; this.score += amount * 2; this.shake = 0.08;
  }

  private loot() {
    sound.chest(); this.score += 60;
    const r = Math.random();
    if (r < 0.3) { this.boost = 22; this.hunger = 100; this.energy = 100; this.cb.onEvent('¡Coco dorado! Energía infinita', '#facc15'); }
    else if (r < 0.55) { this.health = Math.min(100, this.health + 50); this.cb.onEvent('¡Botiquín! +50 salud', '#4ade80'); }
    else { const m = 3 + Math.floor(Math.random() * 3), s = 2 + Math.floor(Math.random() * 3); this.inv.madera += m; this.inv.piedra += s; this.inv.fruta += 2; this.cb.onEvent(`Cofre: +${m} madera, +${s} piedra, +2 fruta`, '#fde68a'); }
  }

  private spawnLogic(dt: number, night: boolean) {
    const p = this.player.pos, d = this.diff, day = this.day;
    if (night) {
      this.spawnCd -= dt;
      if (this.spawnCd <= 0 && this.crabs.hostileCount() < Math.min(d.maxCrabs, 3 + day * 2)) {
        this.spawnCd = Math.max(1.3, 6 - day * 0.7) / d.crabRate;
        const pt = this.crabs.beachPoint(p.x, p.z, 16, 30);
        if (pt) {
          const r = Math.random();
          const type: CrabType = day >= (d.id === 'naufrago' ? 2 : 3) && r < 0.2 ? 'gigante' : day >= 2 && r < 0.5 ? 'azul' : 'rojo';
          this.crabs.spawn(type, pt.x, pt.z);
        }
      }
    } else if ((this.passiveCd -= dt) <= 0) {
      this.passiveCd = 5;
      if (this.crabs.count < 5) { const pt = this.crabs.beachPoint(p.x, p.z, 14, 30); if (pt) this.crabs.spawn('peque', pt.x, pt.z); }
    }
  }

  private update(dt: number) {
    const inp = this.input, d = this.diff;
    while (inp.craftQueue.length) { const k = inp.craftQueue.shift()!; const r = RECIPES.find(x => x.key === k); if (r) this.craft(r.id); }
    if (inp.eatPressed()) this.eat();
    this.t += dt / d.dayLen;
    const night = isNight(this.t);
    if (night && !this.wasNight) { sound.nightfall(); sound.night = true; this.cb.onEvent('Cae la noche… ¡vienen los cangrejos!', '#93c5fd'); }
    if (this.day !== this.dayShown) {
      this.dayShown = this.day; sound.night = false; this.score += 150;
      if (this.day > d.goal) { this.end(true, '¡Un barco te ha rescatado!'); return; }
      sound.dawn(); this.cb.onEvent(this.day === d.goal ? `Día ${this.day} · ¡Hoy llega el rescate!` : `Día ${this.day} · Amanece`, '#fde68a');
      for (let i = 0; i < 2; i++) { const pt = this.crabs.beachPoint(this.player.pos.x, this.player.pos.z, 15, 45); if (pt) this.props.spawnChest(pt.x, pt.z); }
    }
    this.wasNight = night;
    const fire = this.props.nearFire(this.player.pos, 6);
    const running = inp.run && inp.move > 0.1 && (this.energy > 3 || this.boost > 0);
    const dist = this.player.update(dt, inp.move, inp.turn, running, (this.energy <= 0 ? 0.6 : 1) * (this.boost > 0 ? 1.25 : 1), this.flora);
    this.boost = Math.max(0, this.boost - dt);
    if (running && this.boost <= 0) this.energy -= 9 * dt; else this.energy += (dist < 0.01 ? 3.5 : 1.6) * dt;
    if (fire) { this.energy += 8 * dt; this.health += 2 * dt; }
    this.hunger -= d.hunger * dt * (running ? 1.6 : 1) * (this.player.swim ? 1.4 : 1);
    if (this.hunger <= 0) { this.hunger = 0; this.health -= 2.5 * dt; if (this.health <= 0) { this.end(false, 'Moriste de hambre'); return; } }
    else if (this.hunger > 55) this.health += 0.6 * dt;
    this.health = Math.min(100, this.health); this.energy = Math.max(0, Math.min(100, this.energy));
    this.actCd -= dt;
    if ((inp.actPressed() || inp.actHeld()) && this.actCd <= 0) this.action();
    this.spawnLogic(dt, night);
    this.crabs.update(dt, { player: this.player.pos, night, fires: this.props.firePositions(), dmgK: d.crabDmg });
    this.hurtFlash = Math.max(0, this.hurtFlash - dt * 2);
    this.score += dt * 0.5;
    this.prompt = this.computePrompt();
  }

  private computePrompt() {
    const p = this.player.pos, f = this.player.forward;
    if (this.props.nearChest(p, 2.4)) return 'Espacio: abrir cofre';
    const fire = this.props.nearFire(p, 2.6);
    if (fire && fire.fuel < FIRE_FUEL - 20) return this.inv.madera >= 2 ? 'Espacio: añadir leña (2 madera)' : 'La fogata necesita leña';
    const n = this.flora.nearest(p.x, p.z, f.x, f.z, 2.1);
    if (n) return n.kind === 'palm' ? 'Espacio: talar palmera' : n.kind === 'rock' ? 'Espacio: picar roca' : 'Espacio: recoger fruta';
    if (this.hunger < 30 && this.inv.fruta > 0) return 'E: comer fruta';
    return '';
  }

  private snapCamera() { this.cameraTarget(); this.camera.position.copy(this.camPos); this.camera.lookAt(this.camLook); }
  private cameraTarget() {
    const p = this.player.pos, f = this.player.forward;
    this.camPos.set(p.x - f.x * 7.2, Math.max(p.y, 0) + 3.7, p.z - f.z * 7.2);
    this.camPos.y = Math.max(this.camPos.y, heightAt(this.camPos.x, this.camPos.z) + 1.2);
    this.camLook.set(p.x + f.x * 2.5, Math.max(p.y, -0.4) + 1.5, p.z + f.z * 2.5);
  }

  private emitHud() {
    this.cb.onHud({
      health: Math.max(0, this.health), hunger: this.hunger, energy: this.energy, day: this.day, goal: this.diff.goal, clock: clock(this.t),
      night: isNight(this.t), dayFrac: this.t % 1, inv: { ...this.inv }, tools: { ...this.tools }, score: Math.round(this.score), prompt: this.prompt,
      boost: this.boost, hurt: this.hurtFlash, threats: this.crabs.hostileCount(),
    });
  }

  private loop = (now: number) => {
    this.raf = requestAnimationFrame(this.loop);
    // Paso fijo: cada sub-paso ≤ 0.05 s; si un fotograma tarda (equipos lentos) se recupera hasta 0.25 s.
    const frame = Math.min(0.25, Math.max(0, (now - this.last) / 1000)), steps = Math.max(1, Math.ceil(frame / 0.05)), dt = frame / steps; this.last = now;
    if (!this.paused) this.elapsed += frame;
    const focus = this.player.pos;
    if (this.mode === 'attract') {
      const a = this.elapsed * 0.05 + 0.4;
      this.camera.position.set(Math.cos(a) * 118, 30, Math.sin(a) * 118);
      this.camera.lookAt(0, 4, 0);
      this.world.setTime(0.728, new THREE.Vector3(0, 0, 0), this.camera.position, this.elapsed, true);
      this.flora.update(dt, this.elapsed);
    } else {
      if (this.mode === 'play' && !this.paused) {
        for (let i = 0; i < steps && this.mode === 'play'; i++) {
          this.update(dt);
          this.flora.update(dt, this.elapsed);
          this.props.update(dt, this.elapsed, this.world.night);
        }
        if ((this.hudCd -= frame) <= 0) { this.hudCd = 0.1; this.emitHud(); }
      }
      this.cameraTarget();
      const k = Math.min(1, frame * 5);
      this.camera.position.lerp(this.camPos, k);
      this.camera.position.y = Math.max(this.camera.position.y, heightAt(this.camera.position.x, this.camera.position.z) + 1);
      this.shake = Math.max(0, this.shake - frame);
      const s = this.shake * 0.6;
      this.camera.lookAt(this.camLook.x + (Math.random() - 0.5) * s, this.camLook.y + (Math.random() - 0.5) * s, this.camLook.z);
      this.world.setTime(this.t, focus, this.camera.position, this.elapsed);
    }
    this.renderer.render(this.scene, this.camera);
  };

  dispose() {
    cancelAnimationFrame(this.raf); this.ro.disconnect(); this.input.dispose();
    this.world.dispose(); this.flora.dispose(); this.player.dispose(); this.crabs.dispose(); this.props.dispose();
    this.renderer.dispose(); this.renderer.domElement.remove();
  }
}

import * as THREE from 'three';
import { heightAt, ISLAND_R, rng } from './world';
import { lin, mergeColored } from './three-compat';

export type NodeKind = 'palm' | 'rock' | 'bush';
export interface ResNode { kind: NodeKind; x: number; z: number; y: number; hp: number; max: number; regrow: number; idx: number; s: number; rot: number; wob: number; r: number }

// ---------- Geometrías low-poly ----------
function frond(len: number, ang: number, tilt: number) {
  const pos: number[] = [], S = 7;
  const pt = (t: number, side: number) => {
    const w = Math.sin(Math.PI * Math.min(1, t * 1.15)) * 0.42 + 0.03;
    return new THREE.Vector3(t * len, 0.55 * t * len * (1 - t) * 1.2 - t * t * len * 0.55 - Math.abs(side) * w * 0.25, side * w);
  };
  for (let i = 0; i < S; i++) {
    const a = i / S, b = (i + 1) / S;
    for (const sd of [-1, 1]) {
      const p0 = pt(a, 0), p1 = pt(b, 0), p2 = pt(b, sd), p3 = pt(a, sd);
      pos.push(...p0.toArray(), ...p1.toArray(), ...p2.toArray(), ...p0.toArray(), ...p2.toArray(), ...p3.toArray());
    }
  }
  const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.applyMatrix4(new THREE.Matrix4().makeRotationFromEuler(new THREE.Euler(0, ang, tilt, 'YXZ')));
  return g;
}

function palmGeometry() {
  const parts: Array<{ g: THREE.BufferGeometry; color: string; m?: THREE.Matrix4 }> = [];
  const top = new THREE.Vector3();
  for (let i = 0; i < 7; i++) {
    const y = i * 0.95, lean = 0.035 * Math.pow(y, 1.7), r0 = 0.27 - i * 0.017;
    const m = new THREE.Matrix4().compose(new THREE.Vector3(lean, y + 0.5, 0), new THREE.Quaternion().setFromEuler(new THREE.Euler(0, 0, -0.04 * i)), new THREE.Vector3(1, 1, 1));
    parts.push({ g: new THREE.CylinderGeometry(r0 - 0.02, r0, 1.0, 7), color: i % 2 ? '#8b6b46' : '#a5825a', m });
    top.set(lean + 0.05, y + 1.0, 0);
  }
  for (let i = 0; i < 9; i++) {
    const m = new THREE.Matrix4().makeTranslation(top.x, top.y, top.z);
    parts.push({ g: frond(3.2 + (i % 3) * 0.4, (i / 9) * Math.PI * 2 + (i % 2) * 0.2, 0.15 + (i % 2) * 0.25), color: i % 2 ? '#3f9a3b' : '#5cb84a', m });
  }
  for (let i = 0; i < 3; i++) {
    const a = i * 2.1, m = new THREE.Matrix4().makeTranslation(top.x + Math.cos(a) * 0.25, top.y - 0.3, Math.sin(a) * 0.25);
    parts.push({ g: new THREE.IcosahedronGeometry(0.2, 0), color: '#7a5226', m });
  }
  parts.push({ g: new THREE.IcosahedronGeometry(0.32, 0), color: '#5b7d2e', m: new THREE.Matrix4().makeTranslation(top.x, top.y - 0.05, 0) });
  return mergeColored(parts);
}

function rockGeometry() {
  const jitter = (g: THREE.BufferGeometry, k: number) => {
    const p = g.getAttribute('position');
    for (let i = 0; i < p.count; i++) {
      const x = p.getX(i), y = p.getY(i), z = p.getZ(i), h = Math.sin(x * 12.9898 + y * 78.233 + z * 37.719) * 43758.5453, f = 1 + (h - Math.floor(h) - 0.5) * k;
      p.setXYZ(i, x * f, y * f, z * f);
    }
    return g;
  };
  return mergeColored([
    { g: jitter(new THREE.DodecahedronGeometry(1, 0), 0.35), color: '#918b7f', m: new THREE.Matrix4().makeTranslation(0, 0.35, 0) },
    { g: jitter(new THREE.DodecahedronGeometry(0.45, 0), 0.4), color: '#a49e90', m: new THREE.Matrix4().makeTranslation(0.95, 0.05, 0.4) },
    { g: jitter(new THREE.DodecahedronGeometry(0.3, 0), 0.4), color: '#7d786d', m: new THREE.Matrix4().makeTranslation(-0.7, 0, -0.6) },
  ]);
}

function bushGeometry() {
  return mergeColored([0, 1, 2, 3].map(i => ({
    g: new THREE.IcosahedronGeometry(0.7 - i * 0.08, 0), color: i % 2 ? '#3d8a37' : '#4fa543',
    m: new THREE.Matrix4().makeTranslation(Math.cos(i * 1.7) * 0.5, 0.55 + (i === 3 ? 0.35 : 0), Math.sin(i * 1.7) * 0.5),
  })));
}
function fruitGeometry() {
  return mergeColored([0, 1, 2, 3, 4, 5, 6].map(i => ({
    g: new THREE.IcosahedronGeometry(0.14, 0), color: i % 3 === 0 ? '#ff9f1c' : '#e63946',
    m: new THREE.Matrix4().makeTranslation(Math.cos(i * 2.4) * 0.72, 0.5 + (i % 3) * 0.28, Math.sin(i * 2.4) * 0.72),
  })));
}

const HIDDEN = new THREE.Matrix4().makeScale(0.0001, 0.0001, 0.0001);

export class Flora {
  readonly group = new THREE.Group();
  readonly nodes: ResNode[] = [];
  private palms: THREE.InstancedMesh; private stumps: THREE.InstancedMesh; private rocks: THREE.InstancedMesh;
  private bushes: THREE.InstancedMesh; private fruit: THREE.InstancedMesh;
  private sway = { value: 0 };
  private m = new THREE.Matrix4(); private q = new THREE.Quaternion(); private e = new THREE.Euler(); private v = new THREE.Vector3(); private sc = new THREE.Vector3();
  readonly spawn: { x: number; z: number; yaw: number };

  constructor() {
    const r = rng(1234);
    const vmat = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.9, side: THREE.DoubleSide });
    const palmMat = vmat.clone();
    palmMat.onBeforeCompile = sh => {
      sh.uniforms.uSway = this.sway;
      sh.vertexShader = 'uniform float uSway;\n' + sh.vertexShader.replace('#include <begin_vertex>', `#include <begin_vertex>
        #ifdef USE_INSTANCING
        float ph = instanceMatrix[3].x * 0.31 + instanceMatrix[3].z * 0.17;
        #else
        float ph = 0.0;
        #endif
        float yy = max(transformed.y - 1.0, 0.0);
        transformed.x += sin(uSway * 1.3 + ph) * 0.006 * yy * yy; transformed.z += cos(uSway * 1.05 + ph) * 0.004 * yy * yy;`);
    };
    // Punto de aparición: en la playa, mirando a lo largo de la costa
    const sa = 0.55; let sd = ISLAND_R;
    while (sd > 10 && heightAt(Math.cos(sa) * sd, Math.sin(sa) * sd) < 0.6) sd -= 0.5;
    this.spawn = { x: Math.cos(sa) * sd, z: Math.sin(sa) * sd, yaw: -sa };

    const place = (kind: NodeKind, count: number, ok: (h: number) => boolean, minD: number) => {
      const out: ResNode[] = [];
      for (let tries = 0; out.length < count && tries < count * 60; tries++) {
        const a = r() * Math.PI * 2, d = Math.sqrt(r()) * ISLAND_R * 1.05, x = Math.cos(a) * d, z = Math.sin(a) * d, h = heightAt(x, z);
        if (!ok(h) || Math.hypot(x - this.spawn.x, z - this.spawn.z) < 5) continue;
        if (this.nodes.some(n => Math.hypot(n.x - x, n.z - z) < minD)) continue;
        const max = kind === 'bush' ? 3 : 4;
        const n: ResNode = { kind, x, z, y: h, hp: max, max, regrow: 0, idx: out.length, s: 0.8 + r() * 0.5, rot: r() * 6.28, wob: 0, r: kind === 'palm' ? 0.45 : kind === 'rock' ? 1 : 0 };
        if (kind === 'rock') { n.s = 0.7 + r() * 1.1; n.r = 0.9 * n.s; }
        out.push(n); this.nodes.push(n);
      }
      return out;
    };
    // Palmeras extra junto al inicio para que la acción empiece al momento
    const near: ResNode[] = [];
    for (let i = 0; i < 4; i++) {
      const a = this.spawn.yaw + (i === 0 ? 0.32 : (i - 2) * 0.5), d = i === 0 ? 3.1 : 5 + i * 2.5, x = this.spawn.x + Math.sin(a) * d, z = this.spawn.z + Math.cos(a) * d, h = heightAt(x, z);
      if (h > 0.2) { const n: ResNode = { kind: 'palm', x, z, y: h, hp: 4, max: 4, regrow: 0, idx: near.length, s: 0.9 + i * 0.08, rot: i * 2, wob: 0, r: 0.45 }; near.push(n); this.nodes.push(n); }
    }
    const palms = [...near, ...place('palm', 80 - near.length, h => h > 0.35 && h < 6, 3.2)];
    palms.forEach((n, i) => (n.idx = i));
    const rocks = place('rock', 55, h => h > 0.25 && h < 16, 3.5);
    const bushes = place('bush', 45, h => h > 1.7 && h < 9, 3.5);

    this.palms = new THREE.InstancedMesh(palmGeometry(), palmMat, palms.length);
    this.stumps = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.24, 0.3, 0.5, 7), new THREE.MeshStandardMaterial({ color: lin('#8b6b46'), flatShading: true }), palms.length);
    this.rocks = new THREE.InstancedMesh(rockGeometry(), vmat, rocks.length);
    this.bushes = new THREE.InstancedMesh(bushGeometry(), vmat, bushes.length);
    this.fruit = new THREE.InstancedMesh(fruitGeometry(), new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.4, emissive: lin('#331100') }), bushes.length);
    for (const im of [this.palms, this.rocks, this.bushes, this.stumps]) { im.castShadow = true; im.receiveShadow = true; }
    this.nodes.forEach(n => this.write(n));
    this.group.add(this.palms, this.stumps, this.rocks, this.bushes, this.fruit);
    this.decor(r);
  }

  private decor(r: () => number) {
    // Matas de hierba en la zona verde y estrellas de mar / conchas en la arena
    const blade = mergeColored([0, 1, 2].map(i => ({ g: new THREE.ConeGeometry(0.09, 0.8, 3), color: '#ffffff', m: new THREE.Matrix4().compose(new THREE.Vector3(Math.cos(i * 2.1) * 0.12, 0.35, Math.sin(i * 2.1) * 0.12), new THREE.Quaternion().setFromEuler(new THREE.Euler(Math.cos(i * 2.1) * 0.35, 0, Math.sin(i * 2.1) * 0.35)), new THREE.Vector3(1, 1, 1)) })));
    const grass = new THREE.InstancedMesh(blade, new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 1 }), 600);
    const star = mergeColored([0, 1, 2, 3, 4].map(i => ({ g: new THREE.BoxGeometry(0.42, 0.06, 0.1), color: '#ff7b54', m: new THREE.Matrix4().compose(new THREE.Vector3(Math.cos(i * 1.2566) * 0.2, 0.03, Math.sin(i * 1.2566) * 0.2), new THREE.Quaternion().setFromEuler(new THREE.Euler(0, -i * 1.2566, 0)), new THREE.Vector3(1, 1, 1)) })));
    const stars = new THREE.InstancedMesh(star, new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true }), 70);
    const c = new THREE.Color();
    let gi = 0, si = 0;
    for (let t = 0; t < 6000 && (gi < 600 || si < 70); t++) {
      const a = r() * 6.283, d = Math.sqrt(r()) * ISLAND_R * 1.1, x = Math.cos(a) * d, z = Math.sin(a) * d, h = heightAt(x, z);
      this.e.set(0, r() * 6.28, 0); this.q.setFromEuler(this.e);
      if (h > 2.6 && h < 12 && gi < 600) {
        this.m.compose(this.v.set(x, h - 0.05, z), this.q, this.sc.setScalar(0.7 + r() * 0.8)); grass.setMatrixAt(gi, this.m);
        grass.setColorAt(gi++, c.copy(lin(r() > 0.5 ? '#6fb043' : '#8cc152')));
      } else if (h > 0.15 && h < 1.0 && si < 70) {
        this.m.compose(this.v.set(x, h, z), this.q, this.sc.setScalar(0.6 + r() * 0.6)); stars.setMatrixAt(si, this.m);
        stars.setColorAt(si++, c.copy(lin(['#ffffff', '#ffd6a5', '#ffadad', '#fdffb6'][Math.floor(r() * 4)])));
      }
    }
    grass.count = gi; stars.count = si; stars.receiveShadow = true;
    this.group.add(grass, stars);
  }

  private write(n: ResNode) {
    const alive = n.hp > 0, wob = Math.sin(n.wob * 40) * n.wob * 0.5;
    this.e.set(wob * 0.3, n.rot, wob * 0.2); this.q.setFromEuler(this.e);
    if (n.kind === 'rock') this.sc.set(n.s * 1.2, n.s * 0.85, n.s); else this.sc.setScalar(n.s * (1 + Math.abs(wob) * 0.1));
    this.m.compose(this.v.set(n.x, n.y - 0.15, n.z), this.q, this.sc);
    const im = n.kind === 'palm' ? this.palms : n.kind === 'rock' ? this.rocks : this.fruit;
    im.setMatrixAt(n.idx, alive ? this.m : HIDDEN); im.instanceMatrix.needsUpdate = true;
    if (n.kind === 'palm') { this.stumps.setMatrixAt(n.idx, alive ? HIDDEN : this.m.compose(this.v.set(n.x, n.y + 0.1, n.z), this.q, this.sc.setScalar(n.s))); this.stumps.instanceMatrix.needsUpdate = true; }
    if (n.kind === 'bush') { this.m.compose(this.v.set(n.x, n.y - 0.15, n.z), this.q, this.sc.setScalar(n.s)); this.bushes.setMatrixAt(n.idx, this.m); this.bushes.instanceMatrix.needsUpdate = true; }
  }

  /** Recurso más cercano frente al jugador. */
  nearest(x: number, z: number, fx: number, fz: number, range: number) {
    let best: ResNode | null = null, bd = Infinity;
    for (const n of this.nodes) {
      if (n.hp <= 0) continue;
      const dx = n.x - x, dz = n.z - z, d = Math.hypot(dx, dz) - n.r * 0.7;
      if (d > range || (d > 0.8 && (dx * fx + dz * fz) / (Math.hypot(dx, dz) || 1) < 0.2)) continue;
      if (d < bd) { bd = d; best = n; }
    }
    return best;
  }
  hit(n: ResNode, dmg: number) {
    n.hp = Math.max(0, n.hp - dmg); n.wob = 0.35;
    if (n.hp <= 0) n.regrow = n.kind === 'bush' ? 45 : 70;
    this.write(n);
    return n.hp <= 0;
  }
  /** Empuja un círculo fuera de troncos y rocas. */
  collide(p: THREE.Vector3, rad: number) {
    for (const n of this.nodes) {
      if (n.hp <= 0 || n.r === 0) continue;
      const dx = p.x - n.x, dz = p.z - n.z, d = Math.hypot(dx, dz), min = n.r + rad;
      if (d < min && d > 0.0001) { p.x = n.x + (dx / d) * min; p.z = n.z + (dz / d) * min; }
    }
  }
  update(dt: number, elapsed: number) {
    this.sway.value = elapsed;
    for (const n of this.nodes) {
      if (n.wob > 0) { n.wob = Math.max(0, n.wob - dt); this.write(n); }
      if (n.hp <= 0 && (n.regrow -= dt) <= 0) { n.hp = n.max; n.wob = 0.3; this.write(n); }
    }
  }
  dispose() {
    this.group.traverse(o => { const m = o as THREE.Mesh; if (m.geometry) m.geometry.dispose(); const mat = m.material as THREE.Material | undefined; if (mat && mat.dispose) mat.dispose(); });
  }
}

// Entrada: teclado (flechas / WASD) escuchado en window + joystick y botones táctiles virtuales.
export interface VirtualPad { x: number; y: number; act: boolean; eat: boolean; run: boolean }

export class Input {
  private keys = new Set<string>();
  readonly virtual: VirtualPad = { x: 0, y: 0, act: false, eat: false, run: false };
  private prev = { act: false, eat: false };
  /** Teclas de crafteo pulsadas (1-4) pendientes de procesar. */
  readonly craftQueue: string[] = [];

  private onDown = (e: KeyboardEvent) => {
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) e.preventDefault();
    if (!e.repeat && /^Digit[1-4]$/.test(e.code)) this.craftQueue.push(e.code.slice(5));
    this.keys.add(e.code);
  };
  private onUp = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private onBlur = () => { this.keys.clear(); };

  constructor() {
    window.addEventListener('keydown', this.onDown);
    window.addEventListener('keyup', this.onUp);
    window.addEventListener('blur', this.onBlur);
  }

  private any(...codes: string[]) { return codes.some(c => this.keys.has(c)); }
  /** Avance (-1..1) */
  get move() { return (this.any('ArrowUp', 'KeyW') ? 1 : 0) - (this.any('ArrowDown', 'KeyS') ? 1 : 0) + -this.virtual.y; }
  /** Giro (-1 izquierda .. 1 derecha) */
  get turn() { return (this.any('ArrowRight', 'KeyD') ? 1 : 0) - (this.any('ArrowLeft', 'KeyA') ? 1 : 0) + this.virtual.x; }
  get run() { return this.virtual.run || this.any('ShiftLeft', 'ShiftRight'); }
  private edge(k: 'act' | 'eat', now: boolean) { const e = now && !this.prev[k]; this.prev[k] = now; return e; }
  actPressed() { return this.edge('act', this.virtual.act || this.any('Space', 'KeyJ')); }
  actHeld() { return this.virtual.act || this.any('Space', 'KeyJ'); }
  eatPressed() { return this.edge('eat', this.virtual.eat || this.any('KeyE', 'KeyF')); }

  reset() {
    this.keys.clear(); this.craftQueue.length = 0;
    Object.assign(this.virtual, { x: 0, y: 0, act: false, eat: false, run: false });
  }
  dispose() {
    window.removeEventListener('keydown', this.onDown);
    window.removeEventListener('keyup', this.onUp);
    window.removeEventListener('blur', this.onBlur);
  }
}

import * as THREE from 'three';
import { canvasTexture, lin } from './three-compat';
import { heightAt, ISLAND_R } from './world';
import { Flora } from './flora';

export type ToolId = 'hacha' | 'pico' | 'lanza' | null;

const mat = (c: string, extra: THREE.MeshStandardMaterialParameters = {}) => new THREE.MeshStandardMaterial({ color: lin(c), flatShading: true, roughness: 0.8, ...extra });
function box(w: number, h: number, d: number, m: THREE.Material, x = 0, y = 0, z = 0) {
  const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m); b.position.set(x, y, z); b.castShadow = true; return b;
}

/** Camisa hawaiana procedural. */
function shirtTexture() {
  return canvasTexture(128, 128, g => {
    g.fillStyle = '#e8483a'; g.fillRect(0, 0, 128, 128);
    for (let i = 0; i < 26; i++) {
      const x = (i * 37) % 128, y = (i * 53) % 128, r = 5 + (i % 3) * 2;
      g.fillStyle = i % 2 ? '#ffd166' : '#fff4e6';
      for (let p = 0; p < 5; p++) { g.beginPath(); g.arc(x + Math.cos(p * 1.256) * r, y + Math.sin(p * 1.256) * r, r * 0.6, 0, 7); g.fill(); }
      g.fillStyle = '#2a9d8f'; g.beginPath(); g.arc(x, y, r * 0.45, 0, 7); g.fill();
    }
  });
}

export class Player {
  readonly group = new THREE.Group();
  readonly pos = new THREE.Vector3();
  yaw = 0; speed = 0; swim = false; swing = 0; hurt = 0;
  private phase = 0;
  private body = new THREE.Group(); private legL = new THREE.Group(); private legR = new THREE.Group();
  private armL = new THREE.Group(); private armR = new THREE.Group();
  private tools: Record<string, THREE.Object3D> = {};
  private skinMat = mat('#e0a77a'); private shirtMat: THREE.MeshStandardMaterial;

  constructor() {
    const skin = this.skinMat, shorts = mat('#2b6cb0'), hair = mat('#3b2a1e'), straw = mat('#e9c46a'), band = mat('#9b2226'), dark = mat('#1d1d1d');
    this.shirtMat = new THREE.MeshStandardMaterial({ map: shirtTexture(), flatShading: true, roughness: 0.85 });
    this.group.add(this.body);
    // Piernas (pivotes en la cadera)
    for (const [leg, x] of [[this.legL, -0.15], [this.legR, 0.15]] as Array<[THREE.Group, number]>) {
      leg.position.set(x, 0.95, 0);
      leg.add(box(0.22, 0.42, 0.24, shorts, 0, -0.2, 0), box(0.16, 0.46, 0.17, skin, 0, -0.62, 0), box(0.18, 0.08, 0.28, mat('#8d5a3b'), 0, -0.88, 0.04));
      this.body.add(leg);
    }
    this.body.add(box(0.5, 0.2, 0.3, shorts, 0, 1.0, 0));
    this.body.add(box(0.54, 0.58, 0.32, this.shirtMat, 0, 1.38, 0));
    this.body.add(box(0.36, 0.38, 0.14, mat('#7f5539'), 0, 1.4, -0.22)); // mochila
    const head = new THREE.Group(); head.position.set(0, 1.86, 0);
    head.add(box(0.36, 0.36, 0.34, skin), box(0.38, 0.12, 0.36, hair, 0, 0.14, -0.02), box(0.06, 0.06, 0.02, dark, -0.08, 0.02, 0.18), box(0.06, 0.06, 0.02, dark, 0.08, 0.02, 0.18));
    const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.46, 0.5, 0.04, 10), straw); brim.position.y = 0.2; brim.castShadow = true;
    const crown = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.25, 0.2, 10), straw); crown.position.y = 0.3;
    const ribbon = new THREE.Mesh(new THREE.CylinderGeometry(0.255, 0.255, 0.05, 10), band); ribbon.position.y = 0.24;
    head.add(brim, crown, ribbon);
    this.body.add(head);
    for (const [arm, x] of [[this.armL, -0.36], [this.armR, 0.36]] as Array<[THREE.Group, number]>) {
      arm.position.set(x, 1.6, 0);
      arm.add(box(0.17, 0.26, 0.19, this.shirtMat, 0, -0.08, 0), box(0.13, 0.42, 0.14, skin, 0, -0.38, 0));
      this.body.add(arm);
    }
    // Herramientas en la mano derecha
    const wood = mat('#9c6b3c'), stone = mat('#a8a39a', { roughness: 0.5 });
    const hand = new THREE.Group(); hand.position.set(0, -0.6, 0.05); this.armR.add(hand);
    const axe = new THREE.Group(); axe.add(box(0.06, 0.06, 0.8, wood, 0, 0, 0.3), box(0.06, 0.28, 0.18, stone, 0, 0.1, 0.62));
    const pick = new THREE.Group(); pick.add(box(0.06, 0.06, 0.8, wood, 0, 0, 0.3), box(0.06, 0.5, 0.08, stone, 0, 0, 0.66));
    const spear = new THREE.Group(); spear.add(box(0.05, 0.05, 1.8, wood, 0, 0, 0.5));
    const tip = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.3, 4), stone); tip.rotation.x = Math.PI / 2; tip.position.z = 1.5; spear.add(tip);
    this.tools = { hacha: axe, pico: pick, lanza: spear };
    for (const t of Object.values(this.tools)) { t.visible = false; hand.add(t); }
  }

  setTool(t: ToolId) { for (const [k, o] of Object.entries(this.tools)) o.visible = k === t; }
  reset(x: number, z: number, yaw: number) { this.pos.set(x, heightAt(x, z), z); this.yaw = yaw; this.speed = 0; this.swing = 0; this.hurt = 0; this.sync(); }
  get forward() { return new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw)); }

  /** Devuelve la distancia recorrida en este paso. */
  update(dt: number, move: number, turn: number, run: boolean, slow: number, flora: Flora) {
    this.yaw -= Math.max(-1, Math.min(1, turn)) * 2.7 * dt;
    const mv = Math.max(-1, Math.min(1, move));
    const target = mv * (mv > 0 ? (run ? 9.5 : 5.6) : 3.2) * slow * (this.swim ? 0.55 : 1);
    this.speed += (target - this.speed) * Math.min(1, dt * 8);
    const nx = this.pos.x + Math.sin(this.yaw) * this.speed * dt, nz = this.pos.z + Math.cos(this.yaw) * this.speed * dt;
    const ox = this.pos.x, oz = this.pos.z;
    if (heightAt(nx, nz) > -2.4 && Math.hypot(nx, nz) < ISLAND_R * 1.2) { this.pos.x = nx; this.pos.z = nz; } else this.speed *= 0.5;
    flora.collide(this.pos, 0.35);
    const h = heightAt(this.pos.x, this.pos.z);
    this.swim = h < -0.55;
    const ty = this.swim ? -1.05 + Math.sin(performance.now() * 0.003) * 0.06 : h;
    this.pos.y += (ty - this.pos.y) * Math.min(1, dt * 12);
    const dist = Math.hypot(this.pos.x - ox, this.pos.z - oz);
    this.phase += dist * 2.3 * (this.swim ? 0.6 : 1);
    this.swing = Math.max(0, this.swing - dt * 3.2);
    this.hurt = Math.max(0, this.hurt - dt);
    this.animate(dist / Math.max(dt, 1e-4));
    this.sync();
    return dist;
  }

  private animate(v: number) {
    const k = Math.min(1, v / 5), s = Math.sin(this.phase);
    this.legL.rotation.x = s * 0.85 * k; this.legR.rotation.x = -s * 0.85 * k;
    this.armL.rotation.x = -s * 0.7 * k; this.armR.rotation.x = s * 0.7 * k;
    this.armL.rotation.z = -0.08; this.armR.rotation.z = 0.08;
    this.body.position.y = Math.abs(Math.cos(this.phase)) * 0.08 * k;
    this.body.rotation.x = k * 0.08;
    if (this.swim) {
      const t = performance.now() * 0.006;
      this.armL.rotation.x = -2.2 + Math.sin(t) * 1.2; this.armR.rotation.x = -2.2 - Math.sin(t) * 1.2;
      this.legL.rotation.x = Math.sin(t * 2) * 0.5; this.legR.rotation.x = -Math.sin(t * 2) * 0.5;
      this.body.rotation.x = 0.5;
    }
    if (this.swing > 0) {
      const t = 1 - this.swing;
      this.armR.rotation.x = t < 0.35 ? -2.8 * (t / 0.35) : -2.8 + (t - 0.35) / 0.65 * 3.3;
      this.body.rotation.y = Math.sin(t * Math.PI) * -0.35;
    } else this.body.rotation.y = 0;
    const red = this.hurt > 0 && Math.floor(this.hurt * 14) % 2 === 0;
    this.shirtMat.emissive.setRGB(red ? 0.6 : 0, 0, 0); this.skinMat.emissive.setRGB(red ? 0.5 : 0, 0, 0);
  }
  private sync() { this.group.position.copy(this.pos); this.group.rotation.y = this.yaw; }

  dispose() {
    this.group.traverse(o => { const m = o as THREE.Mesh; if (m.geometry) m.geometry.dispose(); const mt = m.material as THREE.MeshStandardMaterial | undefined; if (mt) { mt.map?.dispose(); mt.dispose(); } });
  }
}

import * as THREE from 'three';
import { LIGHT_K, lin, radialTexture } from './three-compat';
import { heightAt } from './world';

// r155+ usa atenuación física (1/d²): compensamos para que la fogata ilumine igual que en r128.
const PL_K = LIGHT_K > 1 ? 3.2 : 1;
export const FIRE_FUEL = 150;

interface Fire { g: THREE.Group; flames: THREE.Sprite[]; embers: THREE.Sprite[]; glow: THREE.Sprite; light: THREE.PointLight; fuel: number; active: boolean; t: number }
interface Chest { g: THREE.Group; lid: THREE.Object3D; beam: THREE.Sprite; active: boolean; open: number }

/** Fogatas, cofres del naufragio y partículas. */
export class Props {
  readonly group = new THREE.Group();
  readonly fires: Fire[] = [];
  readonly chests: Chest[] = [];
  private flameTex = radialTexture([[0, 'rgba(255,250,200,1)'], [0.25, 'rgba(255,190,60,0.95)'], [0.6, 'rgba(255,90,20,0.45)'], [1, 'rgba(255,40,0,0)']]);
  private glowTex = radialTexture([[0, 'rgba(255,170,80,0.55)'], [1, 'rgba(255,120,40,0)']]);
  private beamTex = radialTexture([[0, 'rgba(255,240,150,0.9)'], [0.5, 'rgba(255,210,90,0.35)'], [1, 'rgba(255,200,80,0)']]);
  private parts: THREE.InstancedMesh; private pdata: Array<{ p: THREE.Vector3; v: THREE.Vector3; life: number; s: number }> = [];
  private disposables: Array<{ dispose(): void }> = [];
  private m = new THREE.Matrix4(); private q = new THREE.Quaternion(); private sc = new THREE.Vector3();

  constructor() {
    const stoneG = new THREE.DodecahedronGeometry(0.22, 0), logG = new THREE.CylinderGeometry(0.1, 0.12, 1.1, 6);
    const stoneM = new THREE.MeshStandardMaterial({ color: lin('#7c776d'), flatShading: true }), logM = new THREE.MeshStandardMaterial({ color: lin('#6b4423'), flatShading: true, emissive: lin('#2a0a00') });
    this.disposables.push(stoneG, logG, stoneM, logM, this.flameTex, this.glowTex, this.beamTex);
    for (let i = 0; i < 3; i++) {
      const g = new THREE.Group();
      for (let k = 0; k < 9; k++) { const s = new THREE.Mesh(stoneG, stoneM); const a = (k / 9) * 6.283; s.position.set(Math.cos(a) * 0.75, 0.08, Math.sin(a) * 0.75); s.rotation.set(k, k * 2, 0); s.castShadow = true; g.add(s); }
      for (let k = 0; k < 4; k++) { const l = new THREE.Mesh(logG, logM); l.rotation.set(Math.PI / 2 - 0.5, (k / 4) * 6.283, 0, 'YXZ'); l.position.y = 0.3; g.add(l); }
      const mk = (tex: THREE.Texture, op = 1) => new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, opacity: op }));
      const flames = [0, 1, 2].map(k => { const s = mk(this.flameTex); s.position.set((k - 1) * 0.15, 0.7, 0); g.add(s); return s; });
      const embers = [0, 1, 2, 3, 4, 5].map(() => { const s = mk(this.flameTex); s.scale.setScalar(0.12); g.add(s); return s; });
      const glow = mk(this.glowTex, 0.9); glow.scale.setScalar(7); glow.position.y = 0.5; g.add(glow);
      const light = new THREE.PointLight(lin('#ff9a3c'), 0, 22, 2); light.position.y = 1.4; g.add(light);
      g.visible = false; this.group.add(g);
      this.fires.push({ g, flames, embers, glow, light, fuel: 0, active: false, t: Math.random() * 10 });
    }
    const wood = new THREE.MeshStandardMaterial({ color: lin('#7a4b26'), flatShading: true }), gold = new THREE.MeshStandardMaterial({ color: lin('#f4c430'), metalness: 0.6, roughness: 0.35, emissive: lin('#3a2a00') });
    const bodyG = new THREE.BoxGeometry(1, 0.6, 0.65), lidG = new THREE.BoxGeometry(1.02, 0.25, 0.67), bandG = new THREE.BoxGeometry(0.1, 0.62, 0.69);
    this.disposables.push(wood, gold, bodyG, lidG, bandG);
    for (let i = 0; i < 3; i++) {
      const g = new THREE.Group();
      const b = new THREE.Mesh(bodyG, wood); b.position.y = 0.3; b.castShadow = true; g.add(b);
      for (const x of [-0.35, 0.35]) { const band = new THREE.Mesh(bandG, gold); band.position.set(x, 0.3, 0); g.add(band); }
      const lid = new THREE.Group(); lid.position.set(0, 0.6, -0.32);
      const lm = new THREE.Mesh(lidG, wood); lm.position.set(0, 0.12, 0.32); lid.add(lm);
      const lock = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.18, 0.06), gold); lock.position.set(0, 0, 0.66); lid.add(lock);
      g.add(lid);
      const beam = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.beamTex, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true }));
      beam.scale.set(1.1, 6, 1); beam.position.y = 2.6; g.add(beam);
      g.visible = false; this.group.add(g);
      this.chests.push({ g, lid, beam, active: false, open: 0 });
    }
    this.parts = new THREE.InstancedMesh(new THREE.BoxGeometry(0.14, 0.14, 0.14), new THREE.MeshStandardMaterial({ flatShading: true, roughness: 0.7 }), 160);
    for (let i = 0; i < 160; i++) { this.pdata.push({ p: new THREE.Vector3(), v: new THREE.Vector3(), life: 0, s: 1 }); this.parts.setMatrixAt(i, new THREE.Matrix4().makeScale(0, 0, 0)); this.parts.setColorAt(i, new THREE.Color(1, 1, 1)); }
    this.parts.frustumCulled = false;
    this.group.add(this.parts);
  }

  // ---------- Fogatas ----------
  activeFires() { return this.fires.filter(f => f.active); }
  firePositions() { return this.activeFires().map(f => f.g.position); }
  placeFire(x: number, z: number) {
    const f = this.fires.find(k => !k.active) ?? this.fires.reduce((a, b) => (a.fuel < b.fuel ? a : b));
    f.active = true; f.fuel = FIRE_FUEL; f.g.position.set(x, heightAt(x, z), z); f.g.visible = true;
    this.burst(f.g.position.clone().setY(f.g.position.y + 0.6), '#ffb03a', 24, 5);
  }
  nearFire(p: THREE.Vector3, r: number) { return this.fires.find(f => f.active && f.g.position.distanceTo(p) < r) ?? null; }

  // ---------- Cofres ----------
  spawnChest(x: number, z: number) {
    const c = this.chests.find(k => !k.active); if (!c) return false;
    c.active = true; c.open = 0; c.lid.rotation.x = 0; c.g.position.set(x, heightAt(x, z), z); c.g.rotation.y = Math.random() * 6.28; c.g.visible = true; c.beam.visible = true;
    return true;
  }
  nearChest(p: THREE.Vector3, r: number) { return this.chests.find(c => c.active && c.open === 0 && c.g.position.distanceTo(p) < r) ?? null; }
  openChest(c: Chest) { c.open = 0.001; c.beam.visible = false; this.burst(c.g.position.clone().setY(c.g.position.y + 0.8), '#ffd23f', 30, 6); }
  clear() { this.fires.forEach(f => { f.active = false; f.g.visible = false; f.light.intensity = 0; }); this.chests.forEach(c => { c.active = false; c.g.visible = false; }); this.pdata.forEach(p => (p.life = 0)); }

  // ---------- Partículas (astillas, piedras, jugo, chispas) ----------
  burst(at: THREE.Vector3, color: string, n: number, speed = 4) {
    const c = lin(color);
    for (let i = 0, j = 0; i < this.pdata.length && j < n; i++) {
      const p = this.pdata[i]; if (p.life > 0) continue;
      p.p.copy(at); p.v.set((Math.random() - 0.5) * speed, Math.random() * speed * 0.9 + 1.5, (Math.random() - 0.5) * speed);
      p.life = 0.6 + Math.random() * 0.6; p.s = 0.6 + Math.random() * 0.9; this.parts.setColorAt(i, c); j++;
    }
    if (this.parts.instanceColor) this.parts.instanceColor.needsUpdate = true;
  }

  update(dt: number, elapsed: number, night: number) {
    for (const f of this.fires) {
      if (!f.active) continue;
      f.fuel -= dt; f.t += dt;
      const k = Math.min(1, f.fuel / 40) * (0.85 + Math.sin(f.t * 13) * 0.08 + Math.sin(f.t * 7.3) * 0.07);
      f.flames.forEach((s, i) => { s.scale.set(0.9 * k + 0.1, (1.5 + Math.sin(f.t * 9 + i * 2) * 0.35) * k, 1); s.position.y = 0.35 + s.scale.y * 0.35; });
      f.embers.forEach((s, i) => { const ph = (f.t * 0.6 + i / 6) % 1; s.position.set(Math.sin(i * 3 + f.t) * 0.3 * ph, 0.6 + ph * 3, Math.cos(i * 2 + f.t) * 0.3 * ph); (s.material as THREE.SpriteMaterial).opacity = (1 - ph) * k; });
      f.glow.scale.setScalar((5 + night * 4) * k);
      f.light.intensity = (1.4 + night * 1.8) * k * LIGHT_K * PL_K;
      if (f.fuel <= 0) { f.active = false; f.g.visible = false; f.light.intensity = 0; }
    }
    for (const c of this.chests) {
      if (!c.active) continue;
      (c.beam.material as THREE.SpriteMaterial).opacity = 0.3 + Math.sin(elapsed * 3) * 0.12;
      if (c.open > 0) { c.open += dt; c.lid.rotation.x = -Math.min(1.9, c.open * 6); if (c.open > 2) { c.active = false; c.g.visible = false; } }
    }
    let any = false;
    this.pdata.forEach((p, i) => {
      if (p.life <= 0) return;
      p.life -= dt; p.v.y -= 14 * dt; p.p.addScaledVector(p.v, dt);
      const gy = heightAt(p.p.x, p.p.z); if (p.p.y < gy + 0.05) { p.p.y = gy + 0.05; p.v.multiplyScalar(0.4); p.v.y = Math.abs(p.v.y) * 0.3; }
      const s = p.life > 0 ? p.s * Math.min(1, p.life * 3) : 0;
      this.q.setFromAxisAngle(p.v.clone().normalize(), p.life * 8);
      this.m.compose(p.p, this.q, this.sc.setScalar(s)); this.parts.setMatrixAt(i, this.m); any = true;
    });
    if (any || this.pdata.some(p => p.life > -1)) this.parts.instanceMatrix.needsUpdate = true;
  }

  dispose() {
    this.disposables.forEach(d => d.dispose());
    this.group.traverse(o => { const s = o as THREE.Sprite; if ((s as any).isSprite) (s.material as THREE.Material).dispose(); });
    this.parts.geometry.dispose(); (this.parts.material as THREE.Material).dispose();
  }
}

import * as THREE from 'three';

// r170 trae gestión de color y r128 no: la desactivamos y linealizamos a mano con lin() → mismo resultado en ambas.
const CM = (THREE as any).ColorManagement;
if (CM && typeof CM.enabled === 'boolean') CM.enabled = false;

/** Multiplica TODAS las intensidades de luz (r155+ usa unidades físicas). */
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1;

/** Color sRGB (#hex) → lineal para materiales, luces, niebla y vertex colors. */
export const lin = (c: string | THREE.Color) => new THREE.Color(c).convertSRGBToLinear();

export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any; const T = THREE as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.SRGBColorSpace; else a.outputEncoding = T.sRGBEncoding;
}

export function srgbTexture(t: THREE.Texture) {
  const a = t as any; const T = THREE as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding;
  return t;
}

/** Color hex → vector sRGB "crudo" para shaders propios (que escriben directo a pantalla). */
export function rawColor(hex: string) {
  const c = new THREE.Color(hex);
  return new THREE.Vector3(c.r, c.g, c.b);
}

export function canvasTexture(w: number, h: number, draw: (g: CanvasRenderingContext2D) => void) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d')!);
  return srgbTexture(new THREE.CanvasTexture(c));
}

/** Degradado radial (llamas, brillos, halos). */
export function radialTexture(stops: Array<[number, string]>, size = 64) {
  return canvasTexture(size, size, g => {
    const h = size / 2, gr = g.createRadialGradient(h, h, 0, h, h, h);
    stops.forEach(([o, c]) => gr.addColorStop(o, c));
    g.fillStyle = gr; g.fillRect(0, 0, size, size);
  });
}

/** Une geometrías (no indexadas) en una sola con color por vértice: 1 draw call por especie de planta/roca. */
export function mergeColored(parts: Array<{ g: THREE.BufferGeometry; color: string; m?: THREE.Matrix4 }>) {
  const pos: number[] = [], col: number[] = [];
  for (const { g, color, m } of parts) {
    const geo = (g.index ? g.toNonIndexed() : g).clone();
    if (m) geo.applyMatrix4(m);
    const p = geo.getAttribute('position'), c = lin(color);
    for (let i = 0; i < p.count; i++) {
      pos.push(p.getX(i), p.getY(i), p.getZ(i));
      const k = 0.92 + Math.random() * 0.16;
      col.push(c.r * k, c.g * k, c.b * k);
    }
    geo.dispose();
  }
  const out = new THREE.BufferGeometry();
  out.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  out.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  out.computeVertexNormals();
  return out;
}

import * as THREE from 'three';
import { lin, LIGHT_K, rawColor } from './three-compat';

// ---------- Ruido (value noise + fbm) ----------
function hash(x: number, y: number) { const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453; return s - Math.floor(s); }
function vnoise(x: number, y: number) {
  const ix = Math.floor(x), iy = Math.floor(y), fx = x - ix, fy = y - iy;
  const u = fx * fx * (3 - 2 * fx), v = fy * fy * (3 - 2 * fy);
  const a = hash(ix, iy), b = hash(ix + 1, iy), c = hash(ix, iy + 1), d = hash(ix + 1, iy + 1);
  return (a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v) * 2 - 1;
}
export function fbm(x: number, y: number, oct = 4) {
  let s = 0, a = 0.5, f = 1;
  for (let i = 0; i < oct; i++) { s += vnoise(x * f, y * f) * a; f *= 2.03; a *= 0.5; }
  return s;
}
export const rng = (seed: number) => () => { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };

// ---------- Isla ----------
export const SIZE = 260, ISLAND_R = 92;
const sstep = (a: number, b: number, x: number) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };

/** Altura del terreno (agua = 0). Playa ancha y suave, colinas verdes y un pico volcánico. */
export function heightAt(x: number, z: number) {
  const d = Math.hypot(x, z) / ISLAND_R + fbm(x * 0.012 + 3.1, z * 0.012 - 1.7) * 0.3;
  let raw = (1 - d) * 16 + fbm(x * 0.045, z * 0.045, 3) * 3 * sstep(0.15, 0.6, 1 - d);
  raw += 13 * Math.exp(-((x + 22) ** 2 + (z + 28) ** 2) / 420);
  if (raw < 0) return Math.max(-10, raw * 0.6);
  if (raw < 4) return raw * 0.32;
  return 1.28 + (raw - 4) * 0.72;
}

function terrainMesh() {
  const seg = 150, g = new THREE.PlaneGeometry(SIZE, SIZE, seg, seg);
  g.rotateX(-Math.PI / 2);
  const p = g.getAttribute('position');
  for (let i = 0; i < p.count; i++) p.setY(i, heightAt(p.getX(i), p.getZ(i)));
  g.computeVertexNormals();
  const n = g.getAttribute('normal'), cols: number[] = [];
  const C = (h: string) => lin(h);
  const sea = C('#2f8f95'), wet = C('#cdb27a'), sand = C('#f2dca8'), sand2 = C('#e9cd92'), grass = C('#74b545'), grass2 = C('#4f9438'), rock = C('#8d8676'), tmp = new THREE.Color();
  for (let i = 0; i < p.count; i++) {
    const x = p.getX(i), z = p.getZ(i), h = p.getY(i), ny = n.getY(i), k = fbm(x * 0.08, z * 0.08, 2);
    if (h < -0.35) tmp.copy(wet).lerp(sea, sstep(-0.3, -6, h));
    else if (h < 0.3) tmp.copy(wet).lerp(sand, sstep(-0.35, 0.3, h));
    else tmp.copy(sand).lerp(sand2, k * 0.5 + 0.5);
    tmp.lerp(tmp.clone().copy(grass).lerp(grass2, k * 0.5 + 0.5), sstep(1.9, 2.8, h + k * 0.6));
    tmp.lerp(rock, Math.max(sstep(0.86, 0.72, ny) * sstep(1.5, 3, h), sstep(13, 16, h)));
    cols.push(tmp.r, tmp.g, tmp.b);
  }
  g.setAttribute('color', new THREE.Float32BufferAttribute(cols, 3));
  const m = new THREE.Mesh(g, new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.95, metalness: 0 }));
  m.receiveShadow = true;
  return m;
}

function heightTexture() {
  const N = 256, data = new Uint8Array(N * N * 4);
  for (let j = 0; j < N; j++) for (let i = 0; i < N; i++) {
    const h = heightAt((i / (N - 1) - 0.5) * SIZE, (j / (N - 1) - 0.5) * SIZE), v = Math.round(Math.min(1, Math.max(0, (h + 10) / 28)) * 255), o = (j * N + i) * 4;
    data[o] = data[o + 1] = data[o + 2] = v; data[o + 3] = 255;
  }
  const t = new THREE.DataTexture(data, N, N, THREE.RGBAFormat);
  t.magFilter = THREE.LinearFilter; t.minFilter = THREE.LinearFilter; t.needsUpdate = true;
  return t;
}

const WAVES = `
float waveH(vec2 p, float t){
  return sin(dot(p, vec2(0.12, 0.05)) + t * 1.1) * 0.32 + sin(dot(p, vec2(-0.07, 0.11)) + t * 0.9) * 0.26
       + sin(dot(p, vec2(0.21, -0.17)) + t * 1.7) * 0.1 + sin(dot(p, vec2(-0.33, -0.27)) + t * 2.3) * 0.05;
}
float depthAt(vec2 w){ return -(texture2D(uHeight, w / ${SIZE.toFixed(1)} + 0.5).r * 28.0 - 10.0); }`;

function waterMaterial(hTex: THREE.Texture) {
  return new THREE.ShaderMaterial({
    transparent: true, depthWrite: false,
    uniforms: {
      uTime: { value: 0 }, uHeight: { value: hTex }, uDeep: { value: rawColor('#0b5f9e') }, uShallow: { value: rawColor('#3fe0d0') },
      uSky: { value: rawColor('#bfe8ff') }, uSunDir: { value: new THREE.Vector3(0, 1, 0) }, uSunCol: { value: rawColor('#fff2d6') },
      uFogCol: { value: rawColor('#bfe3f5') }, uFogNear: { value: 60 }, uFogFar: { value: 330 }, uLight: { value: 1 },
    },
    vertexShader: `uniform float uTime; uniform sampler2D uHeight; varying vec3 vW; ${WAVES}
      void main(){ vec4 w = modelMatrix * vec4(position, 1.0); float d = depthAt(w.xz);
        w.y += waveH(w.xz, uTime) * clamp(d / 4.0, 0.12, 1.0); vW = w.xyz; gl_Position = projectionMatrix * viewMatrix * w; }`,
    fragmentShader: `uniform float uTime, uFogNear, uFogFar, uLight; uniform sampler2D uHeight; uniform vec3 uDeep, uShallow, uSky, uSunDir, uSunCol, uFogCol; varying vec3 vW; ${WAVES}
      void main(){
        vec2 p = vW.xz; float d = depthAt(p); float amp = clamp(d / 4.0, 0.12, 1.0); float e = 0.35;
        float r1 = sin(p.x * 1.7 + uTime * 2.1) * sin(p.y * 1.3 - uTime * 1.7) * 0.05;
        float h0 = waveH(p, uTime) * amp + r1;
        float hx = waveH(p + vec2(e, 0.0), uTime) * amp + sin((p.x + e) * 1.7 + uTime * 2.1) * sin(p.y * 1.3 - uTime * 1.7) * 0.05;
        float hz = waveH(p + vec2(0.0, e), uTime) * amp + sin(p.x * 1.7 + uTime * 2.1) * sin((p.y + e) * 1.3 - uTime * 1.7) * 0.05;
        vec3 N = normalize(vec3(h0 - hx, e, h0 - hz));
        vec3 V = normalize(cameraPosition - vW);
        float sh = smoothstep(0.0, 6.0, d);
        vec3 col = mix(uShallow, uDeep, sh);
        float c = sin(p.x * 0.9 + uTime) + sin(p.y * 1.1 - uTime * 1.3) + sin((p.x + p.y) * 0.7 + uTime * 0.7);
        col += vec3(0.25, 0.3, 0.25) * pow(abs(c) / 3.0, 3.0) * (1.0 - sh);
        float fr = pow(1.0 - max(dot(N, V), 0.0), 4.0);
        col = mix(col, uSky, clamp(fr * 0.8, 0.0, 0.7));
        float foam = smoothstep(0.55, 0.0, d + sin(uTime * 1.6 + p.x * 0.2) * 0.12);
        foam += smoothstep(0.1, 0.0, abs(fract(d * 0.7 - uTime * 0.22) - 0.5)) * (1.0 - smoothstep(0.2, 1.8, d)) * 0.7;
        foam *= smoothstep(-0.4, 0.05, d);
        col = mix(col, vec3(1.0), clamp(foam, 0.0, 1.0) * 0.9) * uLight;
        vec3 L = normalize(uSunDir); float spec = pow(max(dot(reflect(-L, N), V), 0.0), 180.0);
        col += uSunCol * spec * 1.6 * step(0.0, L.y);
        float a = mix(0.45, 0.94, smoothstep(0.0, 3.0, d)) + foam * 0.5;
        float f = smoothstep(uFogNear, uFogFar, length(vW - cameraPosition));
        gl_FragColor = vec4(mix(col, uFogCol, f), clamp(a, 0.0, 1.0) * smoothstep(-0.6, -0.15, d) + f);
      }`,
  });
}

function skyMaterial() {
  return new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false, fog: false,
    uniforms: { uTop: { value: rawColor('#2f8fe0') }, uHorizon: { value: rawColor('#bfe8ff') }, uFog: { value: rawColor('#bfe3f5') },
      uSun: { value: new THREE.Vector3(0, 1, 0) }, uSunCol: { value: rawColor('#fff2d6') }, uNight: { value: 0 } },
    vertexShader: `varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`,
    fragmentShader: `uniform vec3 uTop, uHorizon, uFog, uSun, uSunCol; uniform float uNight; varying vec3 vDir;
      void main(){ vec3 d = normalize(vDir); float y = d.y;
        vec3 c = mix(uHorizon, uTop, smoothstep(0.0, 0.55, y)); c = mix(c, uFog, smoothstep(0.1, -0.03, y));
        float s = max(dot(d, normalize(uSun)), 0.0); c += uSunCol * (pow(s, 900.0) * 6.0 + pow(s, 14.0) * 0.4) * step(-0.05, uSun.y);
        float m = max(dot(d, -normalize(uSun)), 0.0); c += vec3(0.9, 0.95, 1.0) * (pow(m, 1400.0) * 3.0 + pow(m, 40.0) * 0.15) * uNight;
        gl_FragColor = vec4(c, 1.0); }`,
  });
}

// Paletas por fase del día (sRGB)
const PAL = {
  day: { top: '#2a86de', hor: '#c4ecff', fog: '#bfe3f5', sun: '#fff3dc', hemi: '#cfeaff', gnd: '#e3c98f', deep: '#0b62a3', shal: '#3fe3d2' },
  gold: { top: '#3f6fbf', hor: '#ffc68e', fog: '#f2cfa6', sun: '#ffb46a', hemi: '#ffd9b3', gnd: '#b98f5a', deep: '#1d4f86', shal: '#46c9c0' },
  night: { top: '#040a1e', hor: '#1b2c58', fog: '#16244a', sun: '#8fb0ff', hemi: '#3b5590', gnd: '#1c2238', deep: '#06203f', shal: '#14606a' },
};
type PalKey = keyof typeof PAL.day;

export class World {
  readonly group = new THREE.Group();
  readonly sun = new THREE.DirectionalLight(0xffffff, 1);
  readonly hemi = new THREE.HemisphereLight(0xffffff, 0xffffff, 1);
  readonly fog = new THREE.Fog(0xbfe3f5, 60, 330);
  private water: THREE.ShaderMaterial; private sky: THREE.ShaderMaterial; private skyMesh: THREE.Mesh;
  private stars: THREE.Points; private clouds = new THREE.Group(); private cloudMat: THREE.MeshStandardMaterial;
  private hTex: THREE.DataTexture;
  night = 0; light = 1;

  constructor(scene: THREE.Scene) {
    scene.fog = this.fog;
    this.group.add(terrainMesh());
    this.hTex = heightTexture();
    const wg = new THREE.PlaneGeometry(900, 900, 220, 220); wg.rotateX(-Math.PI / 2);
    this.water = waterMaterial(this.hTex);
    const water = new THREE.Mesh(wg, this.water); water.renderOrder = 2; water.frustumCulled = false;
    this.group.add(water);
    this.sky = skyMaterial();
    this.skyMesh = new THREE.Mesh(new THREE.SphereGeometry(700, 32, 16), this.sky); this.skyMesh.renderOrder = -1; this.skyMesh.frustumCulled = false;
    this.group.add(this.skyMesh);
    const sp: number[] = [], r = rng(7);
    for (let i = 0; i < 700; i++) { const a = r() * Math.PI * 2, y = 0.05 + r() * 0.95, s = Math.sqrt(1 - y * y); sp.push(Math.cos(a) * s * 600, y * 600, Math.sin(a) * s * 600); }
    const sg = new THREE.BufferGeometry(); sg.setAttribute('position', new THREE.Float32BufferAttribute(sp, 3));
    this.stars = new THREE.Points(sg, new THREE.PointsMaterial({ color: 0xffffff, size: 2, sizeAttenuation: false, transparent: true, opacity: 0, fog: false, depthWrite: false }));
    this.stars.frustumCulled = false; this.group.add(this.stars);
    this.cloudMat = new THREE.MeshStandardMaterial({ color: 0xffffff, flatShading: true, roughness: 1, fog: false, transparent: true, opacity: 0.95 });
    const cg = new THREE.IcosahedronGeometry(1, 1);
    for (let i = 0; i < 16; i++) {
      const c = new THREE.Group(), a = r() * Math.PI * 2, d = 170 + r() * 250;
      for (let k = 0; k < 4; k++) { const m = new THREE.Mesh(cg, this.cloudMat); m.position.set((k - 1.5) * 9 + r() * 4, r() * 3, r() * 6); m.scale.set(9 + r() * 6, 5 + r() * 3, 7 + r() * 4); c.add(m); }
      c.position.set(Math.cos(a) * d, 60 + r() * 40, Math.sin(a) * d); c.rotation.y = r() * 3; this.clouds.add(c);
    }
    this.group.add(this.clouds);
    this.sun.castShadow = true;
    this.sun.shadow.mapSize.set(1024, 1024);
    const sc = this.sun.shadow.camera; sc.left = -34; sc.right = 34; sc.top = 34; sc.bottom = -34; sc.near = 1; sc.far = 160;
    this.sun.shadow.bias = -0.0006;
    this.group.add(this.sun, this.sun.target, this.hemi);
    scene.add(this.group);
  }

  /** Aplica la hora del día t (0..1) a cielo, luces, niebla y agua. focus = punto que sigue la sombra. */
  setTime(t: number, focus: THREE.Vector3, camPos: THREE.Vector3, elapsed: number, far = false) {
    this.fog.near = far ? 170 : 60; this.fog.far = far ? 560 : 330;
    const a = (t - 0.25) * Math.PI * 2, el = Math.sin(a);
    const sunDir = new THREE.Vector3(Math.cos(a) * 0.85, el, 0.42).normalize();
    const day = sstep(0.0, 0.35, el), night = sstep(0.02, -0.14, el), gold = Math.max(0, 1 - day - night);
    this.night = night;
    const mix = (k: PalKey) => {
      const c = new THREE.Color(PAL.day[k]).multiplyScalar(day);
      c.add(new THREE.Color(PAL.gold[k]).multiplyScalar(gold)).add(new THREE.Color(PAL.night[k]).multiplyScalar(night));
      return c;
    };
    const top = mix('top'), hor = mix('hor'), fog = mix('fog'), sunC = mix('sun');
    const lightDir = night > 0.5 ? sunDir.clone().negate() : sunDir;
    this.sun.position.copy(focus).addScaledVector(lightDir, 80);
    this.sun.target.position.copy(focus);
    this.sun.color.copy(lin(sunC));
    this.sun.intensity = (day * 1.4 + gold * 1.25 + night * 0.3) * LIGHT_K;
    this.hemi.color.copy(lin(mix('hemi'))); this.hemi.groundColor.copy(lin(mix('gnd')));
    this.hemi.intensity = (day * 0.75 + gold * 0.65 + night * 0.4) * LIGHT_K;
    this.fog.color.copy(lin(fog));
    this.light = day * 1 + gold * 0.85 + night * 0.38;
    const u = this.sky.uniforms, w = this.water.uniforms;
    u.uTop.value.set(top.r, top.g, top.b); u.uHorizon.value.set(hor.r, hor.g, hor.b); u.uFog.value.set(fog.r, fog.g, fog.b);
    u.uSun.value.copy(sunDir); u.uSunCol.value.set(sunC.r, sunC.g, sunC.b); u.uNight.value = night;
    w.uTime.value = elapsed; w.uSunDir.value.copy(lightDir); w.uSunCol.value.set(sunC.r, sunC.g, sunC.b);
    w.uSky.value.set(hor.r, hor.g, hor.b); w.uFogNear.value = this.fog.near; w.uFogFar.value = this.fog.far; w.uFogCol.value.set(fog.r, fog.g, fog.b); w.uLight.value = this.light;
    const dp = mix('deep'), sh = mix('shal'); w.uDeep.value.set(dp.r, dp.g, dp.b); w.uShallow.value.set(sh.r, sh.g, sh.b);
    (this.stars.material as THREE.PointsMaterial).opacity = night;
    this.skyMesh.position.copy(camPos); this.stars.position.copy(camPos);
    this.cloudMat.color.copy(lin(hor)).lerp(new THREE.Color(1, 1, 1), day * 0.7);
    this.cloudMat.emissive.copy(lin(hor)).multiplyScalar(0.55 + day * 0.2);
    this.clouds.rotation.y = elapsed * 0.004;
  }

  dispose() {
    this.group.traverse(o => { const m = o as THREE.Mesh; if (m.geometry) m.geometry.dispose(); const mat = m.material as THREE.Material | undefined; if (mat && mat.dispose) mat.dispose(); });
    this.hTex.dispose();
  }
}

.ip-root { font-family: 'Trebuchet MS', 'Segoe UI', 'Helvetica Neue', Arial, sans-serif; user-select: none; -webkit-user-select: none; touch-action: none; color: #0b2a33; }

.ip-title {
  font-family: 'Arial Black', 'Trebuchet MS', Impact, sans-serif; font-weight: 900; line-height: 0.88; letter-spacing: 0.01em;
  color: #fff6dc; -webkit-text-stroke: 2px #0b2a33; paint-order: stroke fill;
  text-shadow: 0 5px 0 #0b2a33, 0 12px 30px rgba(11, 42, 51, 0.45);
}
.ip-title .ip-coral { color: #ff6b4a; }
.ip-paper { background: linear-gradient(160deg, rgba(255, 248, 228, 0.96), rgba(246, 231, 193, 0.94)); border: 3px solid #0b2a33; border-radius: 22px; box-shadow: 0 6px 0 #0b2a33, 0 18px 40px rgba(11, 42, 51, 0.35); }
.ip-glass { background: rgba(8, 36, 46, 0.62); border: 1.5px solid rgba(255, 246, 220, 0.35); border-radius: 16px; color: #fff6dc; backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px); box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25); }

.ip-btn { border: 3px solid #0b2a33; border-radius: 16px; box-shadow: 0 5px 0 #0b2a33; font-weight: 900; transition: transform 0.08s, box-shadow 0.08s, filter 0.15s; }
.ip-btn:hover { filter: brightness(1.06); }
.ip-btn:active { transform: translateY(4px); box-shadow: 0 1px 0 #0b2a33; }

.ip-bar { height: 12px; border-radius: 999px; background: rgba(255, 255, 255, 0.16); overflow: hidden; box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.4); }
.ip-bar > div { height: 100%; border-radius: 999px; transition: width 0.15s linear; }

.ip-vignette { pointer-events: none; background: radial-gradient(ellipse at center, rgba(0, 0, 0, 0) 58%, rgba(5, 25, 35, 0.38) 100%); }
.ip-hurt { pointer-events: none; background: radial-gradient(ellipse at center, rgba(255, 0, 0, 0) 45%, rgba(220, 20, 30, 0.55) 100%); }
.ip-waves { background: repeating-radial-gradient(circle at 50% 120%, transparent 0 10px, rgba(255, 255, 255, 0.08) 10px 12px); }

@keyframes ip-toast { 0% { transform: translateY(14px) scale(0.85); opacity: 0; } 12% { transform: translateY(0) scale(1.04); opacity: 1; } 80% { opacity: 1; } 100% { transform: translateY(-14px); opacity: 0; } }
.ip-toast { animation: ip-toast 2.2s ease-out both; }
@keyframes ip-float { 50% { transform: translateY(-7px) rotate(-1.5deg); } }
.ip-float { animation: ip-float 3.4s ease-in-out infinite; }
@keyframes ip-pulse { 50% { opacity: 0.45; } }
.ip-pulse { animation: ip-pulse 0.9s ease-in-out infinite; }
@keyframes ip-in { from { transform: translateY(18px); opacity: 0; } to { transform: none; opacity: 1; } }
.ip-in { animation: ip-in 0.45s cubic-bezier(0.2, 0.9, 0.3, 1.1) both; }
